		Functions       []string `json:"functions"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	l, err := loadLocation(r.Context(), s.db, body.LocationID)
	if err != nil {
		writeErr(w, errOf(404, "not_found", "location not found"))
		return
	}
	if body.Name == "" || body.Coordinate == nil {
		writeErr(w, errOf(400, "invalid_json", "locationId, name and coordinate are required"))
		return
	}
	if !validCoordinate(body.Coordinate.Latitude, body.Coordinate.Longitude) {
		writeErr(w, errOf(400, "invalid_coordinate", "coordinate is out of range"))
		return
	}
	coverage := l.CoverageKm
	if body.CoverageKm != nil {
		coverage = *body.CoverageKm
	}
	if coverage <= 0 || coverage > 5 {
		writeErr(w, errOf(400, "invalid_node_coverage", "coverageKm must be greater than 0 and at most 5"))
		return
	}
	handling := l.HandlingMinutes
	if body.HandlingMinutes != nil {
		handling = *body.HandlingMinutes
	}
	if handling < 0 || handling > 1440 {
		writeErr(w, errOf(400, "invalid_handling_time", "handlingMinutes must be between 0 and 1440"))
		return
	}
	fns := l.Functions
	if body.Functions != nil {
		if len(body.Functions) == 0 {
			writeErr(w, errOf(400, "invalid_location_function", "at least one function is required"))
