	if body.Active == nil {
		writeErr(w, errOf(400, "invalid_json", "active is required"))
		return
	}
	if _, err := loadConnection(r.Context(), s.db, body.ConnectionID); err != nil {
		writeErr(w, errOf(404, "not_found", "connection not found"))
		return
	}
	if _, err := s.db.Exec(r.Context(), `UPDATE connections SET active=$2 WHERE connection_id=$1`, body.ConnectionID, *body.Active); err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	s.recomputeServiceability(r.Context())
	s.audit(r.Context(), sess, "set_connection_status", "connection", body.ConnectionID, true, map[string]any{"active": *body.Active})
	s.emit(r.Context(), "connection_updated", "connection", body.ConnectionID, map[string]any{"connectionId": body.ConnectionID, "active": *body.Active}, "", "")
	writeData(w, 200, map[string]any{"connectionId": body.ConnectionID, "active": *body.Active})
}

