	}
	_, _ = s.db.Exec(ctx, `UPDATE samples SET serviceability=$2, serviceability_reason=$3 WHERE sample_id=$1`, sampleID, serviceability, reason)

	activeAssignmentIDs := []string{}
	journeyID := ""
	labID := ""
	if res.Serviceable {
		sample, _ := loadSample(ctx, s.db, sampleID)
		req, _ := loadRequest(ctx, s.db, requestID)
		j, aerr := s.createJourneyPlan(ctx, sess, sample, req, st, res.EntryID, res.Route, now, true, sess.User.UserID)
