			_, _ = s.db.Exec(ctx, `UPDATE samples SET serviceability='unserviceable', serviceability_reason='insufficient_capacity' WHERE sample_id=$1`, sampleID)
			serviceability = "unserviceable"
			reason = "insufficient_capacity"
		} else {
			journeyID = j.JourneyID
			labID = res.LabID
			_, _ = s.db.Exec(ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3, status=$4 WHERE sample_id=$1`,
				sampleID, journeyID, labID, SampleAtNode)
			s.kickOffers(ctx, sess, journeyID)
			for _, a := range journeyAssignments(ctx, s.db, journeyID) {
				if a.Status == AsgOffered || a.Status == AsgAccepted || a.Status == AsgPending {
					activeAssignmentIDs = append(activeAssignmentIDs, a.AssignmentID)
				}
			}
		}
	}
	s.audit(ctx, sess, "ingest_presealed_sample", "sample", sampleID, true,
		map[string]any{"requestId": requestID, "serviceability": serviceability})
	s.audit(ctx, sess, "custody", "sample", sampleID, true, map[string]any{"holderId": sess.User.UserID, "note": "registered pre-sealed"})
	s.emit(ctx, "sample_status", "sample", sampleID, map[string]any{"sampleId": sampleID, "status": SampleSealed}, "", "")
	out := map[string]any{
		"requestId":            requestID,
		"sampleId":             sampleID,
		"serviceability":       serviceability,
		"serviceabilityReason": reason,
		"activeAssignmentIds":  activeAssignmentIDs,
		"earliestCollectionAt": fmtTime(earliest),
		"latestCollectionAt":   fmtTime(latest),
		"alreadySealed":        true,
		"originType":           body.OriginType,
	}
	if journeyID != "" {
		out["journeyId"] = journeyID
	}
	if labID != "" {
		out["targetLaboratoryId"] = labID
