	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes_NewReader(raw))
	var body struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "accept_assignment", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		a, err := loadAssignment(ctx, s.db, body.AssignmentID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "assignment not found")
		}
		if kindRole(a.Kind) != sess.ActiveRole && sess.ActiveRole != RoleAdmin {
			return 403, nil, errOf(403, "ineligible_worker", "the selected role may not accept this kind of assignment")
		}
		switch a.Status {
		case AsgOffered:
			if a.OfferedTo == nil || *a.OfferedTo != sess.User.UserID {
				return 403, nil, errOf(403, "ineligible_worker", "this assignment was offered to another worker")
			}
		case AsgPending:
			return 409, nil, errOf(409, "offer_not_available", "this assignment is not currently offered")
		case AsgAccepted, AsgInProgress:
			if a.AcceptedBy != nil && *a.AcceptedBy == sess.User.UserID {
				return 201, assignmentJSON(a), nil
			}
			return 409, nil, errOf(409, "assignment_taken", "this assignment was already accepted")
		default:
			return 409, nil, errOf(409, "assignment_inactive", "this assignment is no longer active")
		}
		if a.OfferExpiresAt != nil && a.OfferExpiresAt.Before(nowUTC()) {
			return 409, nil, errOf(409, "offer_not_available", "the offer has expired")
		}
		if !sess.User.Available {
			return 409, nil, errOf(409, "worker_unavailable", "mark yourself available before accepting work")
		}
		var active int
		_ = s.db.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE accepted_by=$1 AND status IN ('accepted','in_progress')`, sess.User.UserID).Scan(&active)
		if active >= sess.User.CapacityUnits {
			return 409, nil, errOf(409, "worker_unavailable", "you are at your assignment capacity")
		}
		now := nowUTC()
		if _, err := s.db.Exec(ctx, `UPDATE assignments SET status='accepted', accepted_by=$2, accepted_at=$3, updated_at=now()
			WHERE assignment_id=$1 AND status='offered'`, a.AssignmentID, sess.User.UserID, now); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		j, _ := loadJourney(ctx, s.db, a.JourneyID)
		if j != nil && j.Status == JourneyPlanned {
			_, _ = s.db.Exec(ctx, `UPDATE journeys SET status='in_progress', updated_at=now() WHERE journey_id=$1`, j.JourneyID)
		}
		s.audit(ctx, sess, "accept_assignment", "assignment", a.AssignmentID, true, map[string]any{"kind": a.Kind, "sampleId": a.SampleID})
		s.emit(ctx, "assignment_accepted", "assignment", a.AssignmentID, map[string]any{
			"assignmentId": a.AssignmentID, "workerId": sess.User.UserID, "kind": a.Kind, "sampleId": a.SampleID,
		}, "", "")
		s.kickOffers(ctx, sess, a.JourneyID)
		a, _ = loadAssignment(ctx, s.db, a.AssignmentID)
		return 201, assignmentJSON(a), nil
	})
}

func (s *server) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleCollector, RoleCourier, RoleNode, RoleLab, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes_NewReader(raw))
	var body struct {
		AssignmentID   string `json:"assignmentId"`
		DeclinedAt     string `json:"declinedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "decline_assignment", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		a, err := loadAssignment(ctx, s.db, body.AssignmentID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "assignment not found")
		}
		if a.Status != AsgOffered || a.OfferedTo == nil || *a.OfferedTo != sess.User.UserID {
			return 409, nil, errOf(409, "offer_not_available", "this assignment is not currently offered to you")
		}
		declinedAt := nowUTC()
		if body.DeclinedAt != "" {
			t, ok := parseTime(body.DeclinedAt)
			if !ok {
				return 400, nil, errOf(400, "invalid_time", "declinedAt must be an RFC3339 timestamp")
			}
			declinedAt = t
		}
		declined := append(a.DeclinedBy, sess.User.UserID)
		dj, _ := json.Marshal(declined)
		if _, err := s.db.Exec(ctx, `UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL,
			declined_by=$2, updated_at=now() WHERE assignment_id=$1`, a.AssignmentID, dj); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		if _, err := s.db.Exec(ctx, `UPDATE users SET recent_declines = recent_declines + 1, last_decline_at=$2 WHERE user_id=$1`,
			sess.User.UserID, declinedAt); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		s.audit(ctx, sess, "decline_assignment", "assignment", a.AssignmentID, true, map[string]any{"kind": a.Kind, "sampleId": a.SampleID})
		s.emit(ctx, "assignment_declined", "assignment", a.AssignmentID, map[string]any{
			"assignmentId": a.AssignmentID, "workerId": sess.User.UserID, "kind": a.Kind, "sampleId": a.SampleID,
		}, "", "")
		// re-offer to the next eligible worker
		a, _ = loadAssignment(ctx, s.db, a.AssignmentID)
		offeredTo, noQualified, _ := s.offerAssignment(ctx, sess, a)
		if noQualified {
			s.flagNoQualifiedWorker(ctx, sess, a.SampleID, a.AssignmentID)
		}
		out := map[string]any{"assignmentId": a.AssignmentID, "status": "declined"}
		if offeredTo != nil {
			out["reofferedTo"] = *offeredTo
		}
		return 201, out, nil
	})
}

var transportProgressOrder = []string{"at_pickup", "picked_up", "in_transit", "arrived", "delivered"}

func (s *server) handleUpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleCollector, RoleCourier, RoleNode, RoleLab, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes_NewReader(raw))
	var body struct {
		AssignmentID   string `json:"assignmentId"`
		Status         string `json:"status"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "update_assignment_progress", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		a, err := loadAssignment(ctx, s.db, body.AssignmentID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "assignment not found")
		}
		if a.AcceptedBy == nil || *a.AcceptedBy != sess.User.UserID {
			return 403, nil, errOf(403, "forbidden", "only the assigned worker may record progress")
		}
		if a.Status != AsgAccepted && a.Status != AsgInProgress {
			return 409, nil, errOf(409, "assignment_inactive", "this assignment is not active")
		}
		occurredAt := nowUTC()
		if body.OccurredAt != "" {
			t, ok := parseTime(body.OccurredAt)
			if !ok {
				return 400, nil, errOf(400, "invalid_time", "occurredAt must be an RFC3339 timestamp")
			}
			occurredAt = t
		}
		sample, err := loadSample(ctx, s.db, a.SampleID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "sample not found")
		}
		// validate transition
		if a.Kind == KindTransport {
			if !containsString(transportProgressOrder, body.Status) {
				return 409, nil, errOf(409, "invalid_transition", "unknown transport progress status")
			}
			curIdx := -1
			if a.Progress != nil {
				for i, p := range transportProgressOrder {
					if p == *a.Progress {
						curIdx = i
					}
				}
			}
			nextIdx := -1
			for i, p := range transportProgressOrder {
				if p == body.Status {
					nextIdx = i
				}
			}
			if nextIdx <= curIdx {
				return 409, nil, errOf(409, "invalid_transition", "progress may only move forward")
			}
			if (body.Status == "picked_up" || body.Status == "in_transit") &&
				(sample.CurrentHolderID == nil || *sample.CurrentHolderID != sess.User.UserID) {
				return 409, nil, errOf(409, "custody_required", "you must hold custody of the sample before transporting it")
			}
		} else {
			if body.Status != AsgInProgress && body.Status != AsgCompleted {
				return 409, nil, errOf(409, "invalid_transition", "status must be in_progress or completed for this assignment kind")
			}
			if body.Status == AsgCompleted && a.Kind == KindNode {
				// node work completes through the outgoing handoff
				if sample.CurrentHolderID == nil || *sample.CurrentHolderID != sess.User.UserID {
					return 409, nil, errOf(409, "custody_required", "you must hold custody of the sample")
				}
			}
		}
		newStatus := AsgInProgress
		var completedAt *time.Time
		if body.Status == AsgCompleted || body.Status == "delivered" {
			newStatus = AsgCompleted
			completedAt = &occurredAt
		}
		if _, err := s.db.Exec(ctx, `UPDATE assignments SET status=$2, progress=$3, completed_at=COALESCE($4, completed_at), updated_at=now()
			WHERE assignment_id=$1`, a.AssignmentID, newStatus, body.Status, completedAt); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		// sample-level effects
		switch body.Status {
		case "picked_up", "in_transit":
			if sample.Status != SampleInTransit {
				s.setSampleStatus(ctx, sess, sample.SampleID, SampleInTransit, map[string]any{"assignmentId": a.AssignmentID})
			}
		case "delivered":
			if a.ToLocationID != nil {
				_, _ = s.db.Exec(ctx, `UPDATE samples SET latest_lat=(SELECT lat FROM locations WHERE location_id=$2),
					latest_lng=(SELECT lng FROM locations WHERE location_id=$2), location_recorded_at=$3, updated_at=now()
					WHERE sample_id=$1`, sample.SampleID, *a.ToLocationID, occurredAt)
			}
		}
		// deadline check
		req, _ := loadRequest(ctx, s.db, sample.RequestID)
		if req != nil && occurredAt.After(req.DeliveryDeadline) && sample.Status != SampleReceived {
			s.markSampleException(ctx, sess, sample.SampleID, "deadline_missed", "the delivery deadline has passed")
		}
		s.audit(ctx, sess, "update_assignment_progress", "assignment", a.AssignmentID, true,
			map[string]any{"status": body.Status, "sampleId": a.SampleID})
		s.emit(ctx, "assignment_progress", "assignment", a.AssignmentID, map[string]any{
			"assignmentId": a.AssignmentID, "status": body.Status, "sampleId": a.SampleID,
		}, "", "")
		s.kickOffers(ctx, sess, a.JourneyID)
		return 201, map[string]any{"assignmentId": a.AssignmentID, "status": newStatus, "progress": body.Status}, nil
	})
}

func (s *server) markSampleException(ctx context.Context, sess *session, sampleID, excType, reason string) {
	exc := map[string]any{"type": excType, "reason": reason, "observedAt": fmtTime(nowUTC())}
	excJSON, _ := json.Marshal(exc)
	_, _ = s.db.Exec(ctx, `UPDATE samples SET exception=$2, updated_at=now() WHERE sample_id=$1`, sampleID, excJSON)
	s.setSampleStatus(ctx, sess, sampleID, SampleException, map[string]any{"reason": excType})
	s.emit(ctx, "exception_raised", "sample", sampleID, map[string]any{"sampleId": sampleID, "type": excType}, "", "")
}

func (s *server) handleCollectAndSeal(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleCollector, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes_NewReader(raw))
	var body struct {
		AssignmentID   string  `json:"assignmentId"`
		CollectedAt    string  `json:"collectedAt"`
		ContainerType  string  `json:"containerType"`
		TemperatureC   float64 `json:"temperatureC"`
		IdempotencyKey string  `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "collect_and_seal_sample", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		a, err := loadAssignment(ctx, s.db, body.AssignmentID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "assignment not found")
		}
		if a.Kind != KindCollection {
			return 400, nil, errOf(400, "invalid_json", "assignmentId must reference a collection assignment")
		}
		if a.AcceptedBy == nil || *a.AcceptedBy != sess.User.UserID {
			return 403, nil, errOf(403, "forbidden", "only the assigned collection professional may collect this sample")
		}
		if a.Status != AsgAccepted && a.Status != AsgInProgress {
			return 409, nil, errOf(409, "assignment_inactive", "this collection assignment is not active")
		}
		collectedAt := nowUTC()
		if body.CollectedAt != "" {
			t, ok := parseTime(body.CollectedAt)
			if !ok {
				return 400, nil, errOf(400, "invalid_time", "collectedAt must be an RFC3339 timestamp")
			}
			collectedAt = t
		}
		sample, err := loadSample(ctx, s.db, a.SampleID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "sample not found")
		}
		if sample.Sealed {
			return 409, nil, errOf(409, "invalid_assignment_state", "the sample is already sealed")
		}
		req, err := loadRequest(ctx, s.db, sample.RequestID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "request not found")
		}
		st, err := loadSampleType(ctx, s.db, req.SampleTypeID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "sample type not found")
		}
		if collectedAt.Before(req.EarliestCollection) || collectedAt.After(req.LatestCollection) {
			return 409, nil, errOf(409, "outside_collection_window", "collectedAt is outside the collection window")
		}
		if st.QualifiedRequired && !workerQualified(sess.User, st) {
			return 409, nil, errOf(409, "certification_inactive", "you do not hold an active certification for this sample type")
		}
		if body.ContainerType != "" && st.ContainerType != "" && body.ContainerType != st.ContainerType {
			return 400, nil, errOf(400, "handling_noncompliant", "containerType does not match the required container")
		}
		handlingCompliant := body.TemperatureC >= st.TempMinC && body.TemperatureC <= st.TempMaxC
		now := nowUTC()
		if _, err := s.db.Exec(ctx, `UPDATE samples SET sealed=TRUE, sealed_at=$2, current_holder_id=$3, updated_at=now()
			WHERE sample_id=$1`, sample.SampleID, collectedAt, sess.User.UserID); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		if _, err := s.db.Exec(ctx, `UPDATE assignments SET status='completed', progress='completed', completed_at=$2, updated_at=now()
			WHERE assignment_id=$1`, a.AssignmentID, now); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		s.setSampleStatus(ctx, sess, sample.SampleID, SampleSealed, map[string]any{"assignmentId": a.AssignmentID})
		s.audit(ctx, sess, "collect_and_seal", "sample", sample.SampleID, true,
			map[string]any{"assignmentId": a.AssignmentID, "collectedAt": fmtTime(collectedAt), "containerType": body.ContainerType, "temperatureC": body.TemperatureC})
		s.emit(ctx, "sample_sealed", "sample", sample.SampleID, map[string]any{"sampleId": sample.SampleID, "collectorId": sess.User.UserID}, "", "")
		if !handlingCompliant {
			s.markSampleException(ctx, sess, sample.SampleID, "temperature_excursion", "observed temperature is outside the required range")
		}
		s.kickOffers(ctx, sess, a.JourneyID)
		return 201, map[string]any{
			"sampleId":          sample.SampleID,
			"sealed":            true,
			"sealedAt":          fmtTime(collectedAt),
			"handlingCompliant": handlingCompliant,
		}, nil
	})
}

func (s *server) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleCollector, RoleCourier, RoleNode, RoleLab, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		AssignmentID string   `json:"assignmentId"`
		Coordinate   *coordIn `json:"coordinate"`
		RecordedAt   string   `json:"recordedAt"`
		Sequence     *int     `json:"sequence"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	if body.Coordinate == nil || !validCoordinate(body.Coordinate.Latitude, body.Coordinate.Longitude) {
		writeErr(w, errOf(400, "invalid_coordinate", "coordinate must be a valid latitude/longitude"))
		return
	}
	if body.Sequence == nil || *body.Sequence < 1 {
		writeErr(w, errOf(400, "invalid_sequence", "sequence must be a positive integer"))
		return
	}
	recordedAt := nowUTC()
	if body.RecordedAt != "" {
		t, ok := parseTime(body.RecordedAt)
		if !ok {
			writeErr(w, errOf(400, "invalid_time", "recordedAt must be an RFC3339 timestamp"))
			return
		}
		recordedAt = t
	}
	ctx := r.Context()
	a, err := loadAssignment(ctx, s.db, body.AssignmentID)
	if err != nil {
		writeErr(w, errOf(404, "not_found", "assignment not found"))
		return
	}
	if a.AcceptedBy == nil || *a.AcceptedBy != sess.User.UserID {
		writeErr(w, errOf(403, "forbidden", "only the assigned worker may record locations for this assignment"))
		return
	}
	if *body.Sequence <= a.LastLocationSeq {
		writeErr(w, errOf(400, "invalid_sequence", "sequence must increase with each location update"))
		return
	}
	if a.LastLocationSeq > 0 {
		var lastAt time.Time
		if err := s.db.QueryRow(ctx, `SELECT last_location_at FROM assignments WHERE assignment_id=$1`, a.AssignmentID).Scan(&lastAt); err == nil {
			if recordedAt.Before(lastAt) {
				writeErr(w, errOf(409, "stale_location", "recordedAt is older than the last recorded location"))
				return
			}
		}
	}
	if _, err := s.db.Exec(ctx, `UPDATE assignments SET last_location_seq=$2, last_location_at=$3, updated_at=now() WHERE assignment_id=$1`,
		a.AssignmentID, *body.Sequence, recordedAt); err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	if _, err := s.db.Exec(ctx, `UPDATE users SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4 WHERE user_id=$1`,
		sess.User.UserID, body.Coordinate.Latitude, body.Coordinate.Longitude, recordedAt); err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	// If the worker currently holds the sample, the sample moves with them.
	sample, err := loadSample(ctx, s.db, a.SampleID)
	if err == nil && sample.CurrentHolderID != nil && *sample.CurrentHolderID == sess.User.UserID {
		_, _ = s.db.Exec(ctx, `UPDATE samples SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4, updated_at=now() WHERE sample_id=$1`,
			sample.SampleID, body.Coordinate.Latitude, body.Coordinate.Longitude, recordedAt)
		s.emit(ctx, "sample_location", "sample", sample.SampleID, map[string]any{
			"sampleId": sample.SampleID, "latitude": body.Coordinate.Latitude, "longitude": body.Coordinate.Longitude,
		}, "", "")
	}
	s.audit(ctx, sess, "record_worker_location", "assignment", a.AssignmentID, true,
		map[string]any{"sequence": *body.Sequence, "latitude": body.Coordinate.Latitude, "longitude": body.Coordinate.Longitude})
	s.emit(ctx, "worker_location", "user", sess.User.UserID, map[string]any{
		"workerId": sess.User.UserID, "latitude": body.Coordinate.Latitude, "longitude": body.Coordinate.Longitude,
	}, "", "")
	writeData(w, 201, map[string]any{
		"assignmentId": a.AssignmentID,
		"coordinate":   map[string]any{"latitude": body.Coordinate.Latitude, "longitude": body.Coordinate.Longitude},
		"recordedAt":   fmtTime(recordedAt),
		"sequence":     *body.Sequence,
	})
}

func (s *server) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleCollector, RoleCourier, RoleNode, RoleLab, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes_NewReader(raw))
	var body struct {
		SampleID             string  `json:"sampleId"`
		AssignmentID         string  `json:"assignmentId"`
		LocationID           string  `json:"locationId"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		RecordedAt           string  `json:"recordedAt"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "record_handling_checkpoint", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		sample, err := loadSample(ctx, s.db, body.SampleID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "sample not found")
		}
		if sample.Status == SampleReceived || sample.Status == SampleExpired || sample.Status == SampleCancelled {
			return 409, nil, errOf(409, "terminal_sample", "the sample's journey has already ended")
		}
		if sample.CurrentHolderID == nil || *sample.CurrentHolderID != sess.User.UserID {
			return 403, nil, errOf(403, "forbidden", "only the current holder may record a handling checkpoint")
		}
		a, err := loadAssignment(ctx, s.db, body.AssignmentID)
		if err != nil || a.SampleID != sample.SampleID {
			return 404, nil, errOf(404, "not_found", "assignment not found for this sample")
		}
		if a.AcceptedBy == nil || *a.AcceptedBy != sess.User.UserID ||
			(a.Status != AsgAccepted && a.Status != AsgInProgress && a.Status != AsgCompleted) {
			return 409, nil, errOf(409, "assignment_inactive", "the assignment is not active")
		}
		recordedAt := nowUTC()
		if body.RecordedAt != "" {
			t, ok := parseTime(body.RecordedAt)
			if !ok {
				return 400, nil, errOf(400, "invalid_time", "recordedAt must be an RFC3339 timestamp")
			}
			recordedAt = t
		}
		req, _ := loadRequest(ctx, s.db, sample.RequestID)
		st, _ := loadSampleType(ctx, s.db, req.SampleTypeID)
		compliant := true
		if body.ContainerType != "" && st.ContainerType != "" && body.ContainerType != st.ContainerType {
			compliant = false
		}
		if body.ObservedTemperatureC < st.TempMinC || body.ObservedTemperatureC > st.TempMaxC {
			compliant = false
		}
		checkpointID := newUUID()
		var locID *string
		if body.LocationID != "" && isUUID(body.LocationID) {
			locID = &body.LocationID
		}
		if _, err := s.db.Exec(ctx, `INSERT INTO checkpoints (checkpoint_id, sample_id, assignment_id, location_id, actor_id,
			container_type, observed_temperature_c, compliant, recorded_at) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
			checkpointID, sample.SampleID, a.AssignmentID, locID, sess.User.UserID,
			body.ContainerType, body.ObservedTemperatureC, compliant, recordedAt); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		s.audit(ctx, sess, "handling_checkpoint", "sample", sample.SampleID, true,
			map[string]any{"checkpointId": checkpointID, "compliant": compliant, "observedTemperatureC": body.ObservedTemperatureC})
		if !compliant {
			s.markSampleException(ctx, sess, sample.SampleID, "handling_noncompliant", "observed container or temperature is outside the required range")
		}
		sample, _ = loadSample(ctx, s.db, sample.SampleID)
		return 201, map[string]any{
			"checkpointId": checkpointID,
			"compliant":    compliant,
			"sampleStatus": sample.Status,
		}, nil
	})
}
"}

{"command":"create","path":"/workspace/server/handoffs.go","file_text":"package main

import (
	"bytes"
	"io"
	"net/http"
	"time"
)

func handoffJSON(h *Handoff, currentHolderID *string) map[string]any {
	out := map[string]any{
		"handoffId":         h.HandoffID,
		"status":            h.Status,
		"senderConfirmed":   h.SenderConfirmed,
		"receiverConfirmed": h.ReceiverConfirmed,
	}
	if currentHolderID != nil {
		out["currentHolderId"] = *currentHolderID
	}
	return out
}

// assignmentLocation returns the location where the assignment's holder is
// expected to be when handing off.
func assignmentLocation(a *Assignment) *string {
	switch a.Kind {
	case KindCollection, KindTransport:
		return a.ToLocationID
	case KindNode:
		return a.NodeID
	case KindLab:
		return a.LaboratoryID
	}
	return nil
}

func (s *server) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleCollector, RoleCourier, RoleNode, RoleLab, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		SampleID         string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID   string `json:"toAssignmentId"`
		ReceiverID       string `json:"receiverId"`
		InitiatedAt      string `json:"initiatedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "initiate_handoff", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		sample, err := loadSample(ctx, s.db, body.SampleID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "sample not found")
		}
		if sample.CurrentHolderID == nil || *sample.CurrentHolderID != sess.User.UserID {
			return 409, nil, errOf(409, "not_current_holder", "only the current holder may initiate a handoff")
		}
		if sample.PendingHandoffID != nil {
			return 409, nil, errOf(409, "pending_handoff_exists", "a handoff is already pending for this sample")
		}
		from, err := loadAssignment(ctx, s.db, body.FromAssignmentID)
		if err != nil || from.SampleID != sample.SampleID {
			return 404, nil, errOf(404, "not_found", "fromAssignment not found for this sample")
		}
		if from.AcceptedBy == nil || *from.AcceptedBy != sess.User.UserID {
			return 403, nil, errOf(403, "sender_assignment_mismatch", "fromAssignment does not belong to you")
		}
		if from.Status != AsgAccepted && from.Status != AsgInProgress && from.Status != AsgCompleted {
			return 409, nil, errOf(409, "invalid_assignment_state", "fromAssignment is not in a handoff-able state")
		}
		to, err := loadAssignment(ctx, s.db, body.ToAssignmentID)
		if err != nil || to.SampleID != sample.SampleID {
			return 404, nil, errOf(404, "not_found", "toAssignment not found for this sample")
		}
		if to.JourneyID != from.JourneyID || to.Sequence != from.Sequence+1 {
			return 409, nil, errOf(409, "nonadjacent_handoff", "assignments are not adjacent steps of the same journey")
		}
		// every earlier assignment must be finished
		var unfinished int
		_ = s.db.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE journey_id=$1 AND sequence < $2
			AND status NOT IN ('completed','cancelled')`, from.JourneyID, from.Sequence).Scan(&unfinished)
		if unfinished > 0 {
			return 409, nil, errOf(409, "prior_leg_incomplete", "an earlier leg of the journey is not complete")
		}
		if to.AcceptedBy == nil {
			return 400, nil, errOf(400, "invalid_receiver", "the receiving assignment has no accepted worker")
		}
		if body.ReceiverID != *to.AcceptedBy {
			return 409, nil, errOf(409, "receiver_assignment_mismatch", "receiverId is not the worker who accepted the receiving assignment")
		}
		// route continuity: the two assignments must meet at the same place
		fromLoc := assignmentLocation(from)
		var toStart *string
		switch to.Kind {
		case KindTransport:
			toStart = to.FromLocationID
		case KindNode:
			toStart = to.NodeID
		case KindLab:
			toStart = to.LaboratoryID
		}
		if fromLoc != nil && toStart != nil && *fromLoc != *toStart {
			return 409, nil, errOf(409, "invalid_handoff_route", "the assignments do not meet at the same location")
		}
		receiver, err := loadUser(ctx, s.db, body.ReceiverID)
		if err != nil {
			return 400, nil, errOf(400, "invalid_receiver", "receiverId does not reference a user")
		}
		if !receiver.Available || !receiver.Active {
			return 409, nil, errOf(409, "receiver_unavailable", "the receiver is not available")
		}
		initiatedAt := nowUTC()
		if body.InitiatedAt != "" {
			t, ok := parseTime(body.InitiatedAt)
			if !ok {
				return 400, nil, errOf(400, "invalid_time", "initiatedAt must be an RFC3339 timestamp")
			}
			initiatedAt = t
		}
		handoffID := newUUID()
		if _, err := s.db.Exec(ctx, `INSERT INTO handoffs (handoff_id, sample_id, journey_id, from_assignment_id, to_assignment_id,
			sender_id, receiver_id, status, initiated_at) VALUES ($1,$2,$3,$4,$5,$6,$7,'pending',$8)`,
			handoffID, sample.SampleID, from.JourneyID, from.AssignmentID, to.AssignmentID,
			sess.User.UserID, body.ReceiverID, initiatedAt); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		if _, err := s.db.Exec(ctx, `UPDATE samples SET pending_handoff_id=$2, updated_at=now() WHERE sample_id=$1`, sample.SampleID, handoffID); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		s.audit(ctx, sess, "initiate_handoff", "handoff", handoffID, true,
			map[string]any{"sampleId": sample.SampleID, "receiverId": body.ReceiverID})
		s.emit(ctx, "handoff_initiated", "handoff", handoffID, map[string]any{
			"handoffId": handoffID, "sampleId": sample.SampleID, "senderId": sess.User.UserID, "receiverId": body.ReceiverID,
		}, "", "")
		return 201, map[string]any{
			"handoffId":         handoffID,
			"status":            "pending",
			"senderConfirmed":   false,
			"receiverConfirmed": false,
		}, nil
	})
}

func (s *server) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleCollector, RoleCourier, RoleNode, RoleLab, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		HandoffID         string `json:"handoffId"`
		ConfirmationSide  string `json:"confirmationSide"`
		ConfirmedAt       string `json:"confirmedAt"`
		IdempotencyKey    string `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "confirm_handoff", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		if body.ConfirmationSide != "sender" && body.ConfirmationSide != "receiver" {
			return 400, nil, errOf(400, "invalid_confirmation_side", "confirmationSide must be sender or receiver")
		}
		h, err := loadHandoff(ctx, s.db, body.HandoffID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "handoff not found")
		}
		if h.Status != "pending" {
			sample, _ := loadSample(ctx, s.db, h.SampleID)
			return 200, handoffJSON(h, sample.CurrentHolderID), nil
		}
		confirmedAt := nowUTC()
		if body.ConfirmedAt != "" {
			t, ok := parseTime(body.ConfirmedAt)
			if !ok {
				return 400, nil, errOf(400, "invalid_time", "confirmedAt must be an RFC3339 timestamp")
			}
			confirmedAt = t
		}
		switch body.ConfirmationSide {
		case "sender":
			if h.SenderID != sess.User.UserID {
				return 403, nil, errOf(403, "forbidden", "only the sender may confirm the sender side")
			}
			if _, err := s.db.Exec(ctx, `UPDATE handoffs SET sender_confirmed=TRUE WHERE handoff_id=$1`, h.HandoffID); err != nil {
				return 500, nil, errOf(500, "internal_error", err.Error())
			}
			h.SenderConfirmed = true
		case "receiver":
			if h.ReceiverID != sess.User.UserID {
				return 403, nil, errOf(403, "forbidden", "only the receiver may confirm the receiver side")
			}
			if _, err := s.db.Exec(ctx, `UPDATE handoffs SET receiver_confirmed=TRUE WHERE handoff_id=$1`, h.HandoffID); err != nil {
				return 500, nil, errOf(500, "internal_error", err.Error())
			}
			h.ReceiverConfirmed = true
		}
		if h.SenderConfirmed && h.ReceiverConfirmed {
			if _, err := s.db.Exec(ctx, `UPDATE handoffs SET status='confirmed', completed_at=$2 WHERE handoff_id=$1 AND status='pending'`,
				h.HandoffID, confirmedAt); err != nil {
				return 500, nil, errOf(500, "internal_error", err.Error())
			}
			h.Status = "confirmed"
			h.CompletedAt = &confirmedAt
			// custody moves to the receiver exactly once
			if _, err := s.db.Exec(ctx, `UPDATE samples SET current_holder_id=$2, pending_handoff_id=NULL, updated_at=now()
				WHERE sample_id=$1 AND pending_handoff_id=$3`, h.SampleID, h.ReceiverID, h.HandoffID); err != nil {
				return 500, nil, errOf(500, "internal_error", err.Error())
			}
			to, _ := loadAssignment(ctx, s.db, h.ToAssignmentID)
			from, _ := loadAssignment(ctx, s.db, h.FromAssignmentID)
			// complete the sending side's assignment
			if from != nil && from.Status != AsgCompleted && from.Status != AsgCancelled {
				_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='completed', completed_at=$2, updated_at=now() WHERE assignment_id=$1`,
					from.AssignmentID, confirmedAt)
			}
			var newStatus string
			if to != nil {
				switch to.Kind {
				case KindTransport:
					newStatus = SampleInTransit
				case KindNode:
					newStatus = SampleAtNode
					_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='in_progress', updated_at=now() WHERE assignment_id=$1 AND status='accepted'`, to.AssignmentID)
				case KindLab:
					newStatus = SampleAtLaboratory
					_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='in_progress', updated_at=now() WHERE assignment_id=$1 AND status='accepted'`, to.AssignmentID)
				}
			}
			if newStatus != "" {
				s.setSampleStatus(ctx, sess, h.SampleID, newStatus, map[string]any{"handoffId": h.HandoffID})
			}
			s.audit(ctx, sess, "custody", "sample", h.SampleID, true,
				map[string]any{"handoffId": h.HandoffID, "from": h.SenderID, "to": h.ReceiverID})
			s.emit(ctx, "custody_changed", "sample", h.SampleID, map[string]any{
				"sampleId": h.SampleID, "holderId": h.ReceiverID, "handoffId": h.HandoffID,
			}, "", "")
			if to != nil {
				s.kickOffers(ctx, sess, to.JourneyID)
			}
		} else {
			s.audit(ctx, sess, "confirm_handoff", "handoff", h.HandoffID, true,
				map[string]any{"side": body.ConfirmationSide, "sampleId": h.SampleID})
			s.emit(ctx, "handoff_confirmed", "handoff", h.HandoffID, map[string]any{
				"handoffId": h.HandoffID, "side": body.ConfirmationSide, "sampleId": h.SampleID,
			}, "", "")
		}
		sample, _ := loadSample(ctx, s.db, h.SampleID)
		return 201, handoffJSON(h, sample.CurrentHolderID), nil
	})
}

func (s *server) handleConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleLab, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		SampleID      string `json:"sampleId"`
		LaboratoryID  string `json:"laboratoryId"`
		ReceivedAt    string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "confirm_laboratory_receipt", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		sample, err := loadSample(ctx, s.db, body.SampleID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "sample not found")
		}
		if sess.ActiveRole == RoleLab {
			if sess.User.AssignedLocationID == nil || *sess.User.AssignedLocationID != body.LaboratoryID {
				return 403, nil, errOf(403, "wrong_laboratory_operator", "you are not assigned to this laboratory")
			}
		}
		if sample.TargetLaboratoryID == nil || *sample.TargetLaboratoryID != body.LaboratoryID {
			return 409, nil, errOf(409, "receipt_not_ready", "this sample is not expected at that laboratory")
		}
		if sample.Status == SampleReceived {
			return 201, map[string]any{
				"sampleId":             sample.SampleID,
				"status":               SampleReceived,
				"receivedLaboratoryId": body.LaboratoryID,
			}, nil
		}
		if sample.PendingHandoffID != nil {
			return 409, nil, errOf(409, "pending_handoff_exists", "a handoff is still pending for this sample")
		}
		if sample.CurrentHolderID == nil || *sample.CurrentHolderID != sess.User.UserID {
			return 409, nil, errOf(409, "receipt_not_ready", "the sample has not been handed off to the laboratory")
		}
		receivedAt := nowUTC()
		if body.ReceivedAt != "" {
			t, ok := parseTime(body.ReceivedAt)
			if !ok {
				return 400, nil, errOf(400, "invalid_time", "receivedAt must be an RFC3339 timestamp")
			}
			receivedAt = t
		}
		req, _ := loadRequest(ctx, s.db, sample.RequestID)
		if req != nil {
			if receivedAt.Before(req.RequestedAt) {
				return 409, nil, errOf(409, "invalid_receipt_time", "receivedAt is before the request was created")
			}
			if receivedAt.After(req.DeliveryDeadline) {
				return 409, nil, errOf(409, "delivery_deadline_exceeded", "receivedAt is after the delivery deadline")
			}
		}
		if _, err := s.db.Exec(ctx, `UPDATE samples SET status=$2, received_laboratory_id=$3, received_at=$4, updated_at=now()
			WHERE sample_id=$1`, sample.SampleID, SampleReceived, body.LaboratoryID, receivedAt); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		// complete the laboratory assignment and, when all samples are in, the journey
		var journeyID string
		if sample.ActiveJourneyID != nil {
			journeyID = *sample.ActiveJourneyID
		}
		_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='completed', completed_at=$2, updated_at=now()
			WHERE sample_id=$1 AND kind='laboratory' AND status IN ('accepted','in_progress')`, sample.SampleID, receivedAt)
		if journeyID != "" {
			var remaining int
			_ = s.db.QueryRow(ctx, `SELECT count(*) FROM journey_samples js JOIN samples sm ON sm.sample_id=js.sample_id
				WHERE js.journey_id=$1 AND sm.status NOT IN ('received','cancelled','expired')`, journeyID).Scan(&remaining)
			if remaining == 0 {
				_, _ = s.db.Exec(ctx, `UPDATE journeys SET status='completed', updated_at=now() WHERE journey_id=$1`, journeyID)
				s.releaseJourneyReservations(ctx, journeyID)
				s.emit(ctx, "journey_completed", "journey", journeyID, map[string]any{"journeyId": journeyID}, "", "")
			}
		}
		s.setSampleStatus(ctx, sess, sample.SampleID, SampleReceived, map[string]any{"laboratoryId": body.LaboratoryID})
		s.audit(ctx, sess, "confirm_laboratory_receipt", "sample", sample.SampleID, true,
			map[string]any{"laboratoryId": body.LaboratoryID, "receivedAt": fmtTime(receivedAt)})
		s.emit(ctx, "sample_received", "sample", sample.SampleID, map[string]any{
			"sampleId": sample.SampleID, "laboratoryId": body.LaboratoryID,
		}, "", "")
		return 201, map[string]any{
			"sampleId":             sample.SampleID,
			"status":               SampleReceived,
			"receivedLaboratoryId": body.LaboratoryID,
		}, nil
	})
}

func (s *server) handleRecordLaboratoryException(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleLab, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		SampleID      string `json:"sampleId"`
		LaboratoryID  string `json:"laboratoryId"`
		Reason        string `json:"reason"`
		ObservedAt    string `json:"observedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "record_laboratory_exception", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		sample, err := loadSample(ctx, s.db, body.SampleID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "sample not found")
		}
		if sess.ActiveRole == RoleLab {
			if sess.User.AssignedLocationID == nil || *sess.User.AssignedLocationID != body.LaboratoryID {
				return 403, nil, errOf(403, "wrong_laboratory_operator", "you are not assigned to this laboratory")
			}
		}
		if body.Reason == "" {
			return 400, nil, errOf(400, "invalid_exception", "reason is required")
		}
		observedAt := nowUTC()
		if body.ObservedAt != "" {
			t, ok := parseTime(body.ObservedAt)
			if !ok {
				return 400, nil, errOf(400, "invalid_time", "observedAt must be an RFC3339 timestamp")
			}
			observedAt = t
		}
		exceptionID := newUUID()
		s.markSampleException(ctx, sess, sample.SampleID, "laboratory_exception", body.Reason)
		s.audit(ctx, sess, "record_laboratory_exception", "sample", sample.SampleID, true,
			map[string]any{"exceptionId": exceptionID, "laboratoryId": body.LaboratoryID, "reason": body.Reason, "observedAt": fmtTime(observedAt)})
		return 201, map[string]any{
			"exceptionId":  exceptionID,
			"sampleId":     sample.SampleID,
			"sampleStatus": SampleException,
		}, nil
	})
}
"}

{"command":"create","path":"/workspace/server/dispatch.go","file_text":"package main

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"net/http"
	"time"
)

// ---------- journey plan serialization ----------

func legJSON(a *Assignment) map[string]any {
	out := map[string]any{
		"assignmentId": a.AssignmentID,
		"sequence":     a.Sequence,
		"status":       a.Status,
		"sampleId":     a.SampleID,
	}
	if a.FromLocationID != nil {
		out["fromLocationId"] = *a.FromLocationID
	}
	if a.ToLocationID != nil {
		out["toLocationId"] = *a.ToLocationID
	}
	worker := a.AcceptedBy
	if worker == nil {
		worker = a.OfferedTo
	}
	if worker != nil {
		out["workerId"] = *worker
	}
	return out
}

func (s *server) journeyPlanJSON(ctx context.Context, j *Journey) map[string]any {
	asgs := journeyAssignments(ctx, s.db, j.JourneyID)
	legs := []map[string]any{}
	collectionIDs := []string{}
	nodeIDs := []string{}
	labIDs := []string{}
	transportIDs := []string{}
	for _, a := range asgs {
		switch a.Kind {
		case KindTransport:
			legs = append(legs, legJSON(a))
			transportIDs = append(transportIDs, a.AssignmentID)
		case KindCollection:
			collectionIDs = append(collectionIDs, a.AssignmentID)
		case KindNode:
			nodeIDs = append(nodeIDs, a.AssignmentID)
		case KindLab:
			labIDs = append(labIDs, a.AssignmentID)
		}
	}
	out := map[string]any{
		"journeyId":                 j.JourneyID,
		"planVersion":               j.PlanVersion,
		"routeMode":                 j.RouteMode,
		"status":                    j.Status,
		"totalCostUnits":            j.TotalCostUnits,
		"sampleIds":                 journeySampleIDs(ctx, s.db, j.JourneyID),
		"stops":                     j.Stops,
		"legs":                      legs,
		"collectionAssignmentIds":   collectionIDs,
		"nodeAssignmentIds":         nodeIDs,
		"laboratoryAssignmentIds":   labIDs,
	}
	if j.ParentJourneyID != nil {
		out["parentJourneyId"] = *j.ParentJourneyID
	}
	if j.EstimatedDeliveryAt != nil {
		out["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
	}
	if len(transportIDs) > 0 {
		out["firstTransportAssignmentId"] = transportIDs[0]
		out["finalTransportAssignmentId"] = transportIDs[len(transportIDs)-1]
		if len(transportIDs) > 2 {
			out["middleTransportAssignmentIds"] = transportIDs[1 : len(transportIDs)-1]
		}
	}
	if j.ReplanStatus != nil {
		out["replanStatus"] = *j.ReplanStatus
	}
	if j.ReplacementJourneyID != nil {
		if rj, err := loadJourney(ctx, s.db, *j.ReplacementJourneyID); err == nil {
			out["replacementJourney"] = s.journeyPlanJSON(ctx, rj)
		}
	}
	return out
}

// ---------- operations state ----------

func (s *server) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin, RoleNode, RoleLab); aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		SampleTypeID string `json:"sampleTypeId"`
	}
	if r.Body != nil && r.ContentLength > 0 {
		if aerr := decodeBody(r, &body); aerr != nil {
			writeErr(w, aerr)
			return
		}
	}
	ctx := r.Context()
	writeData(w, 200, s.operationsState(ctx, body.SampleTypeID))
}

func (s *server) operationsState(ctx context.Context, sampleTypeFilter string) map[string]any {
	// samples
	samples := []map[string]any{}
	srows, err := s.db.Query(ctx, `SELECT sample_id FROM samples ORDER BY created_at`)
	if err == nil {
		ids := []string{}
		for srows.Next() {
			var id string
			_ = srows.Scan(&id)
			ids = append(ids, id)
		}
		srows.Close()
		for _, id := range ids {
			sm, err := loadSample(ctx, s.db, id)
			if err != nil {
				continue
			}
			if sampleTypeFilter != "" {
				req, err := loadRequest(ctx, s.db, sm.RequestID)
				if err != nil || req.SampleTypeID != sampleTypeFilter {
					continue
				}
			}
			samples = append(samples, s.sampleSummaryJSON(ctx, sm))
		}
	}
	// workers
	workers := []map[string]any{}
	wrows, err := s.db.Query(ctx, `SELECT `+userCols+` FROM users WHERE active=TRUE ORDER BY created_at`)
	if err == nil {
		for wrows.Next() {
			u, err := scanUser(wrows)
			if err != nil {
				continue
			}
			isWorker := false
			for _, role := range u.Roles {
				if containsString(workerRoles, role) {
					isWorker = true
				}
			}
			if !isWorker {
				continue
			}
			var asgCount int
			_ = s.db.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE accepted_by=$1 AND status IN ('accepted','in_progress')`, u.UserID).Scan(&asgCount)
			entry := map[string]any{
				"workerId":        u.UserID,
				"roles":           u.Roles,
				"available":       u.Available,
				"assignmentCount": asgCount,
				"locationStale":   staleSince(u.LocationRecordedAt),
			}
			if u.LatestLat != nil && u.LatestLng != nil {
				entry["latestLocation"] = map[string]any{"latitude": *u.LatestLat, "longitude": *u.LatestLng}
			}
			if u.LocationRecordedAt != nil {
				entry["locationRecordedAt"] = fmtTime(*u.LocationRecordedAt)
			}
			workers = append(workers, entry)
		}
		wrows.Close()
	}
	// locations
	locations := []map[string]any{}
	lrows, err := s.db.Query(ctx, `SELECT location_id FROM locations ORDER BY created_at`)
	if err == nil {
		ids := []string{}
		for lrows.Next() {
			var id string
			_ = lrows.Scan(&id)
			ids = append(ids, id)
		}
		lrows.Close()
		for _, id := range ids {
			l, err := loadLocation(ctx, s.db, id)
			if err != nil {
				continue
			}
			locations = append(locations, map[string]any{
				"locationId":      l.LocationID,
				"name":            l.Name,
				"coordinate":      map[string]any{"latitude": l.Lat, "longitude": l.Lng},
				"functions":       l.Functions,
				"active":          l.Active,
				"capacity":        capacityJSON(l.CapacityUnits, l.ReservedUnits, l.CooledCapacity, l.CooledReserved),
				"acceptedSampleTypeIds": l.AcceptedTypeIDs,
			})
		}
	}
	// connections
	connections := []map[string]any{}
	crows, err := s.db.Query(ctx, `SELECT connection_id FROM connections ORDER BY created_at`)
	if err == nil {
		ids := []string{}
		for crows.Next() {
			var id string
			_ = crows.Scan(&id)
			ids = append(ids, id)
		}
		crows.Close()
		for _, id := range ids {
			c, err := loadConnection(ctx, s.db, id)
			if err != nil {
				continue
			}
			connections = append(connections, map[string]any{
				"connectionId":   c.ConnectionID,
				"fromLocationId": c.FromLocationID,
				"toLocationId":   c.ToLocationID,
				"travelMinutes":  c.TravelMinutes,
				"costUnits":      c.CostUnits,
				"cooled":         c.Cooled,
				"active":         c.Active,
				"capacity":       capacityJSON(c.CapacityUnits, c.ReservedUnits, c.CooledCapacity, c.CooledReserved),
			})
		}
	}
	// routes (journey summaries)
	routes := []map[string]any{}
	jrows, err := s.db.Query(ctx, `SELECT journey_id FROM journeys ORDER BY created_at`)
	if err == nil {
		ids := []string{}
		for jrows.Next() {
			var id string
			_ = jrows.Scan(&id)
			ids = append(ids, id)
		}
		jrows.Close()
		for _, id := range ids {
			j, err := loadJourney(ctx, s.db, id)
			if err != nil {
				continue
			}
			entry := map[string]any{
				"journeyId":   j.JourneyID,
				"planVersion": j.PlanVersion,
				"routeMode":   j.RouteMode,
				"status":      j.Status,
				"sampleIds":   journeySampleIDs(ctx, s.db, j.JourneyID),
			}
			if j.EstimatedDeliveryAt != nil {
				entry["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
			}
			routes = append(routes, entry)
		}
	}
	// pending handoffs
	handoffs := []map[string]any{}
	hrows, err := s.db.Query(ctx, `SELECT handoff_id, sample_id, sender_id, receiver_id, status, initiated_at FROM handoffs WHERE status='pending' ORDER BY initiated_at`)
	if err == nil {
		for hrows.Next() {
			var hid, sid, sender, receiver, status string
			var initiated time.Time
			if err := hrows.Scan(&hid, &sid, &sender, &receiver, &status, &initiated); err != nil {
				continue
			}
			handoffs = append(handoffs, map[string]any{
				"handoffId":   hid,
				"sampleId":    sid,
				"senderId":    sender,
				"receiverId":  receiver,
				"status":      status,
				"initiatedAt": fmtTime(initiated),
			})
		}
		hrows.Close()
	}
	// delays: unfinished samples whose deadline is near or passed
	delays := []map[string]any{}
	exceptions := []map[string]any{}
	for _, sm := range samples {
		sid := sm["sampleId"].(string)
		status := sm["status"].(string)
		if status == SampleException || status == SampleExpired {
			exc := map[string]any{"sampleId": sid, "type": status}
			if e, ok := sm["exception"].(map[string]any); ok {
				if t, ok := e["type"].(string); ok {
					exc["type"] = t
				}
				if r, ok := e["reason"].(string); ok {
					exc["reason"] = r
				}
			}
			exceptions = append(exceptions, exc)
			continue
		}
		if status == SampleReceived || status == SampleCancelled {
			continue
		}
		smObj, err := loadSample(ctx, s.db, sid)
		if err != nil {
			continue
		}
		req, err := loadRequest(ctx, s.db, smObj.RequestID)
		if err != nil {
			continue
		}
		now := nowUTC()
		if now.After(req.DeliveryDeadline) {
			delays = append(delays, map[string]any{
				"sampleId": sid, "type": "deadline_missed",
				"detail": "delivery deadline has passed", "observedAt": fmtTime(now),
			})
		} else if now.Add(30 * time.Minute).After(req.DeliveryDeadline) {
			delays = append(delays, map[string]any{
				"sampleId": sid, "type": "deadline_risk",
				"detail": "delivery deadline is within 30 minutes", "observedAt": fmtTime(now),
			})
		}
	}
	// assignment fairness metrics
	spread := 0
	ineligible := 0
	counts := []int{}
	for _, w := range workers {
		counts = append(counts, w["assignmentCount"].(int))
	}
	if len(counts) > 0 {
		min, max := counts[0], counts[0]
		for _, c := range counts {
			if c < min {
				min = c
			}
			if c > max {
				max = c
			}
		}
		spread = max - min
	}
	_ = s.db.QueryRow(ctx, `SELECT count(*) FROM assignments a JOIN journeys j ON j.journey_id=a.journey_id
		WHERE a.status='pending' AND j.status IN ('planned','in_progress')`).Scan(&ineligible)
	return map[string]any{
		"samples":                   samples,
		"workers":                   workers,
		"locations":                 locations,
		"connections":               connections,
		"routes":                    routes,
		"handoffs":                  handoffs,
		"delays":                    delays,
		"exceptions":                exceptions,
		"assignmentCountSpread":     spread,
		"ineligibleAssignmentCount": ineligible,
	}
}

func (s *server) sampleSummaryJSON(ctx context.Context, sm *Sample) map[string]any {
	out := map[string]any{
		"sampleId":       sm.SampleID,
		"status":         sm.Status,
		"sealed":         sm.Sealed,
		"locationStale":  staleSince(sm.LocationRecordedAt),
		"serviceability": sm.Serviceability,
	}
	if sm.CurrentHolderID != nil {
		out["currentHolderId"] = *sm.CurrentHolderID
	}
	if sm.LatestLat != nil && sm.LatestLng != nil {
		out["latestLocation"] = map[string]any{"latitude": *sm.LatestLat, "longitude": *sm.LatestLng}
	}
	if sm.LocationRecordedAt != nil {
		out["locationRecordedAt"] = fmtTime(*sm.LocationRecordedAt)
	}
	if sm.ActiveJourneyID != nil {
		out["activeJourneyId"] = *sm.ActiveJourneyID
	}
	if sm.TargetLaboratoryID != nil {
		out["targetLaboratoryId"] = *sm.TargetLaboratoryID
	}
	if sm.Exception != nil {
		out["exception"] = sm.Exception
	}
	return out
}

// ---------- journey plan read ----------

func (s *server) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if sess.ActiveRole == "" {
		writeErr(w, errOf(409, "role_not_selected", "select an active role before performing this action"))
		return
	}
	ctx := r.Context()
	j, err := loadJourney(ctx, s.db, r.PathValue("journeyId"))
	if err != nil {
		writeErr(w, errOf(404, "not_found", "journey not found"))
		return
	}
	switch sess.ActiveRole {
	case RoleDispatcher, RoleAdmin:
		writeData(w, 200, s.journeyPlanJSON(ctx, j))
		return
	case RoleRequester:
		// requester must own a sample in the journey
		owns := false
		for _, sid := range journeySampleIDs(ctx, s.db, j.JourneyID) {
			sm, err := loadSample(ctx, s.db, sid)
			if err == nil && sm.RequesterID == sess.User.UserID {
				owns = true
				break
			}
		}
		if !owns {
			writeErr(w, errOf(403, "forbidden", "this journey does not belong to you"))
			return
		}
		out := map[string]any{
			"journeyId": j.JourneyID,
			"routeMode": j.RouteMode,
			"status":    j.Status,
		}
		if j.EstimatedDeliveryAt != nil {
			out["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
			out["etaToLaboratory"] = fmtTime(*j.EstimatedDeliveryAt)
		}
		// current location/holder from the requester's sample
		for _, sid := range journeySampleIDs(ctx, s.db, j.JourneyID) {
			sm, err := loadSample(ctx, s.db, sid)
			if err == nil && sm.RequesterID == sess.User.UserID {
				if sm.LatestLat != nil && sm.LatestLng != nil {
					out["currentLocation"] = map[string]any{"latitude": *sm.LatestLat, "longitude": *sm.LatestLng}
				}
				if sm.CurrentHolderID != nil {
					out["currentHolderId"] = *sm.CurrentHolderID
				}
				break
			}
		}
		writeData(w, 200, out)
		return
	default:
		// workers see only their own legs
		asgs := journeyAssignments(ctx, s.db, j.JourneyID)
		mine := []map[string]any{}
		for _, a := range asgs {
			if (a.AcceptedBy != nil && *a.AcceptedBy == sess.User.UserID) ||
				(a.OfferedTo != nil && *a.OfferedTo == sess.User.UserID) {
				mine = append(mine, legJSON(a))
			}
		}
		if len(mine) == 0 {
			writeErr(w, errOf(403, "forbidden", "you have no work in this journey"))
			return
		}
		writeData(w, 200, map[string]any{
			"journeyId":   j.JourneyID,
			"planVersion": j.PlanVersion,
			"routeMode":   j.RouteMode,
			"status":      j.Status,
			"scope":       "assigned_legs",
			"legs":        mine,
		})
		return
	}
}

// ---------- plan version guard ----------

func checkPlanVersion(j *Journey, expected int) *apiError {
	if expected < 1 {
		return errOf(400, "invalid_plan_version", "expectedPlanVersion must be at least 1")
	}
	if j.Status != JourneyPlanned && j.Status != JourneyInProgress {
		return errOf(409, "inactive_plan", "the journey is no longer active")
	}
	if j.PlanVersion != expected {
		return errOf(409, "stale_plan", "the journey plan has changed; reload and retry")
	}
	return nil
}

// ---------- cancel ----------

func (s *server) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		JourneyID           string `json:"journeyId"`
		Reason              string `json:"reason"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "cancel_journey", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		j, err := loadJourney(ctx, s.db, body.JourneyID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "journey not found")
		}
		if aerr := checkPlanVersion(j, body.ExpectedPlanVersion); aerr != nil {
			return aerr.HTTPStatus, nil, aerr
		}
		s.cancelJourneyInternal(ctx, sess, j, body.Reason, JourneyCancelled)
		sampleIDs := journeySampleIDs(ctx, s.db, j.JourneyID)
		for _, sid := range sampleIDs {
			s.setSampleStatus(ctx, sess, sid, SampleCancelled, map[string]any{"journeyId": j.JourneyID, "reason": body.Reason})
		}
		s.audit(ctx, sess, "cancel_journey", "journey", j.JourneyID, true, map[string]any{"reason": body.Reason})
		s.emit(ctx, "journey_cancelled", "journey", j.JourneyID, map[string]any{"journeyId": j.JourneyID}, "", "")
		return 201, map[string]any{"journeyId": j.JourneyID, "status": JourneyCancelled, "sampleIds": sampleIDs}, nil
	})
}

func (s *server) cancelJourneyInternal(ctx context.Context, sess *session, j *Journey, reason string, status string) {
	_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='cancelled', updated_at=now()
		WHERE journey_id=$1 AND status IN ('pending','offered','accepted','in_progress')`, j.JourneyID)
	_, _ = s.db.Exec(ctx, `UPDATE journeys SET status=$2, updated_at=now() WHERE journey_id=$1`, j.JourneyID, status)
	s.releaseJourneyReservations(ctx, j.JourneyID)
	// clear pending handoffs
	_, _ = s.db.Exec(ctx, `UPDATE handoffs SET status='cancelled' WHERE journey_id=$1 AND status='pending'`, j.JourneyID)
	_, _ = s.db.Exec(ctx, `UPDATE samples SET pending_handoff_id=NULL WHERE active_journey_id=$1 AND pending_handoff_id IS NOT NULL`, j.JourneyID)
}

// ---------- replanning ----------

// replanJourney replaces the unfinished part of a journey with a fresh plan.
// Returns (replacementJourneyID, replanStatus, error).
func (s *server) replanJourney(ctx context.Context, sess *session, journeyID string) (string, string, *apiError) {
	j, err := loadJourney(ctx, s.db, journeyID)
	if err != nil {
		return "", "", errOf(404, "not_found", "journey not found")
	}
	if j.Status != JourneyPlanned && j.Status != JourneyInProgress {
		return "", "not_required", nil
	}
	sampleIDs := journeySampleIDs(ctx, s.db, journeyID)
	if len(sampleIDs) == 0 {
		return "", "not_required", nil
	}
	sample, err := loadSample(ctx, s.db, sampleIDs[0])
	if err != nil {
		return "", "", errOf(404, "not_found", "sample not found")
	}
	if sample.Status == SampleReceived || sample.Status == SampleCancelled || sample.Status == SampleExpired {
		return "", "not_required", nil
	}
	req, err := loadRequest(ctx, s.db, sample.RequestID)
	if err != nil {
		return "", "", errOf(404, "not_found", "request not found")
	}
	st, err := loadSampleType(ctx, s.db, req.SampleTypeID)
	if err != nil {
		return "", "", errOf(404, "not_found", "sample type not found")
	}

	// Determine where the remaining plan must start.
	asgs := journeyAssignments(ctx, s.db, journeyID)
	position := ""
	anchorMode := "collection"
	var anchorWorker string
	var preserveAssignment *Assignment
	if j.EntryLocationID != nil {
		position = *j.EntryLocationID
	}
	switch sample.Status {
	case SampleRequested, SampleAwaitingCollection:
		anchorMode = "collection"
	case SampleSealed, SampleAtNode:
		anchorMode = "intake"
		if sample.CurrentHolderID != nil {
			anchorWorker = *sample.CurrentHolderID
		}
		// find the node where the holder is: the accepted/in-progress node assignment
		for _, a := range asgs {
			if a.Kind == KindNode && (a.Status == AsgInProgress || a.Status == AsgAccepted) &&
				a.AcceptedBy != nil && sample.CurrentHolderID != nil && *a.AcceptedBy == *sample.CurrentHolderID && a.NodeID != nil {
				position = *a.NodeID
			}
		}
	case SampleInTransit:
		// preserve the in-progress transport leg; replan from its destination
		for _, a := range asgs {
			if a.Kind == KindTransport && a.Status == AsgInProgress && a.ToLocationID != nil {
				position = *a.ToLocationID
				preserveAssignment = a
			}
		}
		if preserveAssignment == nil {
			// courier holds custody but has not started; replan from the origin of their leg
			for _, a := range asgs {
				if a.Kind == KindTransport && a.Status == AsgAccepted && a.AcceptedBy != nil &&
					sample.CurrentHolderID != nil && *a.AcceptedBy == *sample.CurrentHolderID && a.FromLocationID != nil {
					position = *a.FromLocationID
					anchorMode = "intake"
					anchorWorker = *sample.CurrentHolderID
				}
			}
		} else {
			anchorMode = "node"
		}
	case SampleAtLaboratory:
		return "", "not_required", nil
	default:
		anchorMode = "intake"
		if sample.CurrentHolderID != nil {
			anchorWorker = *sample.CurrentHolderID
		}
	}
	if position == "" {
		return "", "not_required", nil
	}

	locs, conns, err := s.activeNetwork(ctx)
	if err != nil {
		return "", "", errOf(500, "internal_error", err.Error())
	}
	start := nowUTC()
	route := findRoute(locs, conns, position, st, start)
	if route == nil {
		for _, sid := range sampleIDs {
			s.markSampleException(ctx, sess, sid, "no_route", "no valid route is available after replanning")
		}
		_, _ = s.db.Exec(ctx, `UPDATE journeys SET replan_status='exception', updated_at=now() WHERE journey_id=$1`, journeyID)
		return "", "exception", nil
	}
	if route.Arrival.After(req.DeliveryDeadline) {
		for _, sid := range sampleIDs {
			_, _ = s.db.Exec(ctx, `UPDATE samples SET status=$2, updated_at=now() WHERE sample_id=$1`, sid, SampleExpired)
			s.audit(ctx, sess, "status_change", "sample", sid, true, map[string]any{"status": SampleExpired, "reason": "deadline_unreachable_after_replan"})
			s.emit(ctx, "sample_status", "sample", sid, map[string]any{"sampleId": sid, "status": SampleExpired}, "", "")
		}
		_, _ = s.db.Exec(ctx, `UPDATE journeys SET replan_status='expired', updated_at=now() WHERE journey_id=$1`, journeyID)
		return "", "expired", nil
	}

	// Build the replacement journey for every sample of the old journey.
	var replacementID string
	for i, sid := range sampleIDs {
		sm, err := loadSample(ctx, s.db, sid)
		if err != nil {
			continue
		}
		rq, err := loadRequest(ctx, s.db, sm.RequestID)
		if err != nil {
			continue
		}
		stx, err := loadSampleType(ctx, s.db, rq.SampleTypeID)
		if err != nil {
			continue
		}
		var nj *Journey
		var aerr *apiError
		if i == 0 {
			nj, aerr = s.createJourneyPlan(ctx, sess, sm, rq, stx, position, route, start,
				anchorMode == "intake", anchorWorker)
		} else {
			nj, aerr = s.createJourneyPlan(ctx, sess, sm, rq, stx, position, route, start,
				anchorMode == "intake", anchorWorker)
		}
		if aerr != nil {
			return "", "", aerr
		}
		if anchorMode == "collection" {
			// replace the intake anchor with a fresh collection assignment
			_, _ = s.db.Exec(ctx, `DELETE FROM assignments WHERE journey_id=$1 AND kind='node' AND sequence=0`, nj.JourneyID)
			_, _ = s.db.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, sample_id, kind, sequence, status, to_location_id)
				VALUES ($1,$2,$3,'collection',0,'pending',$4)`, newUUID(), nj.JourneyID, sid, position)
		} else if anchorMode == "node" {
			// continuation: the anchor node assignment must be offered, not auto-accepted
			_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='pending', accepted_by=NULL, accepted_at=NULL
				WHERE journey_id=$1 AND kind='node' AND sequence=0`, nj.JourneyID)
		}
		_, _ = s.db.Exec(ctx, `UPDATE journeys SET parent_journey_id=$2, plan_version=$3, route_mode=$4, updated_at=now() WHERE journey_id=$1`,
			nj.JourneyID, journeyID, j.PlanVersion+1, nj.RouteMode)
		_, _ = s.db.Exec(ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3, updated_at=now() WHERE sample_id=$1`,
			sid, nj.JourneyID, route.LabID)
		if len(sampleIDs) > 1 {
			_, _ = s.db.Exec(ctx, `UPDATE journeys SET route_mode='batched' WHERE journey_id=$1`, nj.JourneyID)
		}
		if i == 0 {
			replacementID = nj.JourneyID
		} else {
			// additional samples join the first replacement journey
			_, _ = s.db.Exec(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, replacementID, sid)
			_, _ = s.db.Exec(ctx, `UPDATE samples SET active_journey_id=$2 WHERE sample_id=$1`, sid, replacementID)
			_, _ = s.db.Exec(ctx, `UPDATE assignments SET journey_id=$2 WHERE journey_id=$1`, nj.JourneyID, replacementID)
			_, _ = s.db.Exec(ctx, `UPDATE reservations SET journey_id=$2 WHERE journey_id=$1`, nj.JourneyID, replacementID)
			_, _ = s.db.Exec(ctx, `DELETE FROM journeys WHERE journey_id=$1`, nj.JourneyID)
		}
	}
	// retire the old journey, preserving completed work and custody
	if preserveAssignment != nil {
		_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='cancelled', updated_at=now()
			WHERE journey_id=$1 AND status IN ('pending','offered','accepted')`, journeyID)
	} else {
		_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='cancelled', updated_at=now()
			WHERE journey_id=$1 AND status IN ('pending','offered','accepted','in_progress')`, journeyID)
	}
	_, _ = s.db.Exec(ctx, `UPDATE journeys SET status='replaced', replacement_journey_id=$2, replan_status='replaced', updated_at=now()
		WHERE journey_id=$1`, journeyID, replacementID)
	s.releaseJourneyReservations(ctx, journeyID)
	s.audit(ctx, sess, "replan_journey", "journey", journeyID, true,
		map[string]any{"replacementJourneyId": replacementID})
	s.emit(ctx, "journey_replanned", "journey", journeyID, map[string]any{
		"journeyId": journeyID, "replacementJourneyId": replacementID,
	}, "", "")
	s.kickOffers(ctx, sess, replacementID)
	return replacementID, "replaced", nil
}

func (s *server) handleRerouteJourney(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		JourneyID           string `json:"journeyId"`
		Reason              string `json:"reason"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "reroute_journey", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		j, err := loadJourney(ctx, s.db, body.JourneyID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "journey not found")
		}
		if aerr := checkPlanVersion(j, body.ExpectedPlanVersion); aerr != nil {
			return aerr.HTTPStatus, nil, aerr
		}
		replacementID, status, aerr := s.replanJourney(ctx, sess, body.JourneyID)
		if aerr != nil {
			return aerr.HTTPStatus, nil, aerr
		}
	switch status {
		case "exception":
			return 409, nil, errOf(409, "no_valid_route", "no valid route is available for the remaining work")
		case "expired":
			return 409, nil, errOf(409, "deadline_exceeded", "no route can meet the delivery deadline")
		}
		out := map[string]any{
			"journeyId":    body.JourneyID,
			"replanStatus": status,
		}
		if replacementID != "" {
			out["replacementPlanId"] = replacementID
			if rj, err := loadJourney(ctx, s.db, replacementID); err == nil {
				out["replacementJourney"] = s.journeyPlanJSON(ctx, rj)
			}
		}
		return 201, out, nil
	})
}

func (s *server) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		ResourceType   string   `json:"resourceType"`
		ResourceID     string   `json:"resourceId"`
		Reason         string   `json:"reason"`
		OccurredAt     string   `json:"occurredAt"`
		IdempotencyKey string   `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "report_disruption", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		if !containsString([]string{"worker", "node", "route", "laboratory", "vehicle", "capacity_pool"}, body.ResourceType) {
			return 400, nil, errOf(400, "invalid_json", "resourceType must be worker, node, route, laboratory, vehicle or capacity_pool")
		}
		occurredAt := nowUTC()
		if body.OccurredAt != "" {
			t, ok := parseTime(body.OccurredAt)
			if !ok {
				return 400, nil, errOf(400, "invalid_time", "occurredAt must be an RFC3339 timestamp")
			}
			occurredAt = t
		}
		// find affected active journeys
		affected := map[string]bool{}
		jrows, err := s.db.Query(ctx, `SELECT journey_id, connection_ids, node_ids, entry_location_id, laboratory_id FROM journeys
			WHERE status IN ('planned','in_progress')`)
		if err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		type jrow struct {
			id      string
			conns   []string
			nodes   []string
			entry   *string
			lab     *string
		}
		jlist := []jrow{}
		for jrows.Next() {
			var jr jrow
			var connsB, nodesB []byte
			if err := jrows.Scan(&jr.id, &connsB, &nodesB, &jr.entry, &jr.lab); err != nil {
				continue
			}
			jr.conns = strSlice(jsonAny(connsB))
			jr.nodes = strSlice(jsonAny(nodesB))
			jlist = append(jlist, jr)
		}
		jrows.Close()
		for _, jr := range jlist {
			switch body.ResourceType {
			case "node", "laboratory":
				if containsString(jr.nodes, body.ResourceID) ||
					(jr.lab != nil && *jr.lab == body.ResourceID) ||
					(jr.entry != nil && *jr.entry == body.ResourceID) {
					affected[jr.id] = true
				}
			case "route", "capacity_pool":
				if containsString(jr.conns, body.ResourceID) || containsString(jr.nodes, body.ResourceID) ||
					(jr.lab != nil && *jr.lab == body.ResourceID) || (jr.entry != nil && *jr.entry == body.ResourceID) {
					affected[jr.id] = true
				}
			case "worker", "vehicle":
				var n int
				_ = s.db.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE journey_id=$1
					AND (accepted_by=$2 OR offered_to=$2) AND status IN ('offered','accepted','in_progress')`, jr.id, body.ResourceID).Scan(&n)
				if n > 0 {
					affected[jr.id] = true
				}
			}
		}
		affectedSamples := []string{}
		replacementPlans := []string{}
		worst := "not_required"
		rank := map[string]int{"not_required": 0, "replaced": 1, "expired": 2, "exception": 3}
		for jid := range affected {
			for _, sid := range journeySampleIDs(ctx, s.db, jid) {
				if !containsString(affectedSamples, sid) {
					affectedSamples = append(affectedSamples, sid)
				}
			}
			replID, status, aerr := s.replanJourney(ctx, sess, jid)
			if aerr != nil {
				continue
			}
			if replID != "" {
				replacementPlans = append(replacementPlans, replID)
			}
			if rank[status] > rank[worst] {
				worst = status
			}
		}
		disruptionID := newUUID()
		asJSON, _ := json.Marshal(affectedSamples)
		rpJSON, _ := json.Marshal(replacementPlans)
		if _, err := s.db.Exec(ctx, `INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at,
			affected_sample_ids, replacement_plan_ids, replan_status) VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
			disruptionID, body.ResourceType, body.ResourceID, body.Reason, occurredAt, asJSON, rpJSON, worst); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		s.audit(ctx, sess, "report_disruption", "disruption", disruptionID, true,
			map[string]any{"resourceType": body.ResourceType, "resourceId": body.ResourceID, "replanStatus": worst})
		s.emit(ctx, "disruption_reported", "disruption", disruptionID, map[string]any{
			"disruptionId": disruptionID, "resourceType": body.ResourceType, "resourceId": body.ResourceID,
		}, "", "")
		return 201, map[string]any{
			"disruptionId":       disruptionID,
			"affectedSampleIds":  affectedSamples,
			"replacementPlanIds": replacementPlans,
			"replanStatus":       worst,
		}, nil
	})
}
"}

{"command":"create","path":"/workspace/server/journeys_edit.go","file_text":"package main

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"net/http"
	"time"
)

// rebuildRoute reconstructs a routeResult from a journey's stored structure.
func (s *server) rebuildRoute(ctx context.Context, j *Journey, start time.Time) *routeResult {
	route := &routeResult{
		ConnectionIDs: j.ConnectionIDs,
		NodeIDs:       j.NodeIDs,
	}
	if j.LaboratoryID != nil {
		route.LabID = *j.LaboratoryID
	}
	t := start
	for i, cid := range j.ConnectionIDs {
		c, err := loadConnection(ctx, s.db, cid)
		if err != nil {
			continue
		}
		route.TravelMinutes += c.TravelMinutes
		route.TotalCost += c.CostUnits
		t = t.Add(time.Duration(c.TravelMinutes) * time.Minute)
		if i < len(j.ConnectionIDs)-1 {
			if nl, err := loadLocation(ctx, s.db, c.ToLocationID); err == nil {
				route.HandlingMinutes += nl.HandlingMinutes
				t = t.Add(time.Duration(nl.HandlingMinutes) * time.Minute)
			}
		}
	}
	route.Arrival = t
	return route
}

func (s *server) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		JourneyID           string   `json:"journeyId"`
		SampleIDs           []string `json:"sampleIds"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "split_journey", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		j, err := loadJourney(ctx, s.db, body.JourneyID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "journey not found")
		}
		if aerr := checkPlanVersion(j, body.ExpectedPlanVersion); aerr != nil {
			return aerr.HTTPStatus, nil, aerr
		}
		if len(body.SampleIDs) == 0 {
			return 400, nil, errOf(400, "invalid_sample_set", "sampleIds must not be empty")
		}
		current := journeySampleIDs(ctx, s.db, j.JourneyID)
		for _, sid := range body.SampleIDs {
			if !containsString(current, sid) {
				return 400, nil, errOf(400, "invalid_sample_set", "sampleIds must belong to the journey")
			}
		}
		if len(body.SampleIDs) == len(current) {
			return 400, nil, errOf(400, "invalid_sample_set", "splitting must leave at least one sample in the original journey")
		}
		start := nowUTC()
		route := s.rebuildRoute(ctx, j, start)
		var splitJourneyID string
		for _, sid := range body.SampleIDs {
			sm, err := loadSample(ctx, s.db, sid)
			if err != nil {
				continue
			}
			rq, err := loadRequest(ctx, s.db, sm.RequestID)
			if err != nil {
				continue
			}
			st, err := loadSampleType(ctx, s.db, rq.SampleTypeID)
			if err != nil {
				continue
			}
			if route.Arrival.After(rq.DeliveryDeadline) {
				return 409, nil, errOf(409, "deadline_exceeded", "a split sample can no longer meet its deadline")
			}
			entry := ""
			if j.EntryLocationID != nil {
				entry = *j.EntryLocationID
			}
			preSealed := sm.Sealed
			anchor := ""
			if sm.CurrentHolderID != nil {
				anchor = *sm.CurrentHolderID
			}
			nj, aerr := s.createJourneyPlan(ctx, sess, sm, rq, st, entry, route, start, preSealed, anchor)
			if aerr != nil {
				return aerr.HTTPStatus, nil, aerr
			}
			if !preSealed {
				// keep collection work in the original journey; split journeys start sealed
				_, _ = s.db.Exec(ctx, `DELETE FROM assignments WHERE journey_id=$1 AND kind='collection'`, nj.JourneyID)
			}
			if splitJourneyID == "" {
				splitJourneyID = nj.JourneyID
			} else {
				_, _ = s.db.Exec(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, splitJourneyID, sid)
				_, _ = s.db.Exec(ctx, `UPDATE assignments SET journey_id=$2 WHERE journey_id=$1`, nj.JourneyID, splitJourneyID)
				_, _ = s.db.Exec(ctx, `UPDATE reservations SET journey_id=$2 WHERE journey_id=$1`, nj.JourneyID, splitJourneyID)
				_, _ = s.db.Exec(ctx, `DELETE FROM journeys WHERE journey_id=$1`, nj.JourneyID)
			}
			_, _ = s.db.Exec(ctx, `DELETE FROM journey_samples WHERE journey_id=$1 AND sample_id=$2`, j.JourneyID, sid)
			_, _ = s.db.Exec(ctx, `UPDATE samples SET active_journey_id=$2, updated_at=now() WHERE sample_id=$1`, sid, splitJourneyID)
		}
		_, _ = s.db.Exec(ctx, `UPDATE journeys SET plan_version=plan_version+1, updated_at=now() WHERE journey_id=$1`, j.JourneyID)
		if len(body.SampleIDs) > 1 || len(current)-len(body.SampleIDs) > 1 {
			_, _ = s.db.Exec(ctx, `UPDATE journeys SET route_mode='batched' WHERE journey_id=$1`, splitJourneyID)
		}
		s.audit(ctx, sess, "split_journey", "journey", j.JourneyID, true,
			map[string]any{"splitJourneyId": splitJourneyID, "sampleIds": body.SampleIDs})
		s.emit(ctx, "journey_split", "journey", j.JourneyID, map[string]any{
			"journeyId": j.JourneyID, "splitJourneyId": splitJourneyID,
		}, "", "")
		s.kickOffers(ctx, sess, splitJourneyID)
		j, _ = loadJourney(ctx, s.db, j.JourneyID)
		sj, _ := loadJourney(ctx, s.db, splitJourneyID)
		return 201, map[string]any{
			"journey":      s.journeyPlanJSON(ctx, j),
			"splitJourney": s.journeyPlanJSON(ctx, sj),
		}, nil
	})
}

func (s *server) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "merge_journeys", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		target, err := loadJourney(ctx, s.db, body.TargetJourneyID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "target journey not found")
		}
		if aerr := checkPlanVersion(target, body.ExpectedPlanVersion); aerr != nil {
			return aerr.HTTPStatus, nil, aerr
		}
		if len(body.SourceJourneyIDs) == 0 {
			return 400, nil, errOf(400, "invalid_json", "sourceJourneyIds must not be empty")
		}
		sources := []*Journey{}
		for _, id := range body.SourceJourneyIDs {
			sj, err := loadJourney(ctx, s.db, id)
			if err != nil {
				return 404, nil, errOf(404, "not_found", "source journey not found")
			}
			if sj.Status != JourneyPlanned && sj.Status != JourneyInProgress {
				return 409, nil, errOf(409, "inactive_plan", "a source journey is no longer active")
			}
			sources = append(sources, sj)
		}
		// gather all samples and validate compatibility
		allSampleIDs := journeySampleIDs(ctx, s.db, target.JourneyID)
		for _, sj := range sources {
			allSampleIDs = append(allSampleIDs, journeySampleIDs(ctx, s.db, sj.JourneyID)...)
		}
		types := map[string]*SampleType{}
		for _, sid := range allSampleIDs {
			sm, err := loadSample(ctx, s.db, sid)
			if err != nil {
				return 404, nil, errOf(404, "not_found", "sample not found")
			}
			rq, err := loadRequest(ctx, s.db, sm.RequestID)
			if err != nil {
				return 404, nil, errOf(404, "not_found", "request not found")
			}
			st, err := loadSampleType(ctx, s.db, rq.SampleTypeID)
			if err != nil {
				return 404, nil, errOf(404, "not_found", "sample type not found")
			}
			if !st.BatchingAllowed {
				return 409, nil, errOf(409, "pulse_no_batch", "a time-critical sample may not be combined into a batch")
			}
			types[st.SampleTypeID] = st
			// deadline check against the target ETA
			if target.EstimatedDeliveryAt != nil && target.EstimatedDeliveryAt.After(rq.DeliveryDeadline) {
				return 409, nil, errOf(409, "deadline_exceeded", "a merged sample can no longer meet its deadline")
			}
		}
		for _, st := range types {
			for _, other := range types {
				if st.SampleTypeID == other.SampleTypeID {
					continue
				}
				if containsString(st.IncompatibleIDs, other.SampleTypeID) || containsString(other.IncompatibleIDs, st.SampleTypeID) {
					return 409, nil, errOf(409, "incompatible_batch", "the samples are not allowed to travel together")
				}
			}
		}
		// capacity: reserve one extra unit per added sample on the target route
		type resv struct{ rt, rid string }
		added := []resv{}
		cooled := false
		for _, st := range types {
			if st.RequiresCooled {
				cooled = true
			}
		}
		reserveExtra := func(rt, rid string) *apiError {
			for range body.SourceJourneyIDs {
				var n int
				if rt == "location" {
					if cooled {
						_ = s.db.QueryRow(ctx, `SELECT cooled_capacity_units - cooled_reserved_units FROM locations WHERE location_id=$1`, rid).Scan(&n)
					} else {
						_ = s.db.QueryRow(ctx, `SELECT capacity_units - reserved_units FROM locations WHERE location_id=$1`, rid).Scan(&n)
					}
				} else {
					if cooled {
						_ = s.db.QueryRow(ctx, `SELECT cooled_capacity_units - cooled_reserved_units FROM connections WHERE connection_id=$1`, rid).Scan(&n)
					} else {
						_ = s.db.QueryRow(ctx, `SELECT capacity_units - reserved_units FROM connections WHERE connection_id=$1`, rid).Scan(&n)
					}
				}
				if n < 1 {
					if cooled {
						return errOf(409, "cooled_capacity_exhausted", "cooled capacity is not available for the merged batch")
					}
					return errOf(409, "capacity_exhausted", "capacity is not available for the merged batch")
				}
				if rt == "location" {
					if cooled {
						_, _ = s.db.Exec(ctx, `UPDATE locations SET cooled_reserved_units = cooled_reserved_units + 1 WHERE location_id=$1`, rid)
					} else {
						_, _ = s.db.Exec(ctx, `UPDATE locations SET reserved_units = reserved_units + 1 WHERE location_id=$1`, rid)
					}
				} else {
					if cooled {
						_, _ = s.db.Exec(ctx, `UPDATE connections SET cooled_reserved_units = cooled_reserved_units + 1 WHERE connection_id=$1`, rid)
					} else {
						_, _ = s.db.Exec(ctx, `UPDATE connections SET reserved_units = reserved_units + 1 WHERE connection_id=$1`, rid)
					}
				}
				added = append(added, resv{rt, rid})
			}
			return nil
		}
		resources := []resv{}
		if target.EntryLocationID != nil {
			resources = append(resources, resv{"location", *target.EntryLocationID})
		}
		for _, nid := range target.NodeIDs {
			resources = append(resources, resv{"location", nid})
		}
		if target.LaboratoryID != nil {
			resources = append(resources, resv{"location", *target.LaboratoryID})
		}
		for _, cid := range target.ConnectionIDs {
			resources = append(resources, resv{"connection", cid})
		}
		for _, rv := range resources {
			if aerr := reserveExtra(rv.rt, rv.rid); aerr != nil {
				// roll back extras
				for _, a := range added {
					if a.rt == "location" {
						if cooled {
							_, _ = s.db.Exec(ctx, `UPDATE locations SET cooled_reserved_units = GREATEST(0, cooled_reserved_units - 1) WHERE location_id=$1`, a.rid)
						} else {
							_, _ = s.db.Exec(ctx, `UPDATE locations SET reserved_units = GREATEST(0, reserved_units - 1) WHERE location_id=$1`, a.rid)
						}
					} else {
						if cooled {
							_, _ = s.db.Exec(ctx, `UPDATE connections SET cooled_reserved_units = GREATEST(0, cooled_reserved_units - 1) WHERE connection_id=$1`, a.rid)
						} else {
							_, _ = s.db.Exec(ctx, `UPDATE connections SET reserved_units = GREATEST(0, reserved_units - 1) WHERE connection_id=$1`, a.rid)
						}
					}
				}
				return aerr.HTTPStatus, nil, aerr
			}
		}
		// move samples to the target journey
		mergedIDs := []string{}
		for _, sj := range sources {
			for _, sid := range journeySampleIDs(ctx, s.db, sj.JourneyID) {
				_, _ = s.db.Exec(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, target.JourneyID, sid)
				_, _ = s.db.Exec(ctx, `UPDATE samples SET active_journey_id=$2, updated_at=now() WHERE sample_id=$1`, sid, target.JourneyID)
				_, _ = s.db.Exec(ctx, `INSERT INTO reservations (reservation_id, resource_type, resource_id, journey_id, sample_id, cooled, units)
					SELECT $1, resource_type, resource_id, $2, $3, $4, 1 FROM reservations WHERE journey_id=$5 AND sample_id=$3 AND released=FALSE LIMIT 1`,
					newUUID(), target.JourneyID, sid, cooled, sj.JourneyID)
			}
			mergedIDs = append(mergedIDs, sj.JourneyID)
			s.cancelJourneyInternal(ctx, sess, sj, "merged into "+target.JourneyID, JourneyMerged)
		}
		_, _ = s.db.Exec(ctx, `UPDATE journeys SET route_mode='batched', plan_version=plan_version+1, updated_at=now() WHERE journey_id=$1`, target.JourneyID)
		s.audit(ctx, sess, "merge_journeys", "journey", target.JourneyID, true,
			map[string]any{"mergedJourneyIds": mergedIDs, "sampleIds": allSampleIDs})
		s.emit(ctx, "journey_merged", "journey", target.JourneyID, map[string]any{
			"journeyId": target.JourneyID, "mergedJourneyIds": mergedIDs,
		}, "", "")
		target, _ = loadJourney(ctx, s.db, target.JourneyID)
		return 201, map[string]any{
			"journey":          s.journeyPlanJSON(ctx, target),
			"mergedJourneyIds": mergedIDs,
			"sampleIds":        allSampleIDs,
		}, nil
	})
}

func (s *server) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		JourneyID           string                 `json:"journeyId"`
		ExpectedPlanVersion int                    `json:"expectedPlanVersion"`
		ChangeType          string                 `json:"changeType"`
		Changes             map[string]any         `json:"changes"`
		IdempotencyKey      string                 `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "edit_active_plan", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		j, err := loadJourney(ctx, s.db, body.JourneyID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "journey not found")
		}
		if aerr := checkPlanVersion(j, body.ExpectedPlanVersion); aerr != nil {
			return aerr.HTTPStatus, nil, aerr
		}
		if body.Changes == nil {
			body.Changes = map[string]any{}
		}
		switch body.ChangeType {
		case "replace_worker", "reassign_worker":
			assignmentID, _ := body.Changes["assignmentId"].(string)
			workerID, _ := body.Changes["workerId"].(string)
			if assignmentID == "" || !isUUID(workerID) {
				return 400, nil, errOf(400, "invalid_worker", "changes must include assignmentId and workerId")
			}
			a, err := loadAssignment(ctx, s.db, assignmentID)
			if err != nil || a.JourneyID != j.JourneyID {
				return 404, nil, errOf(404, "not_found", "assignment not found in this journey")
			}
			if a.Status == AsgCompleted || a.Status == AsgCancelled {
				return 409, nil, errOf(409, "inactive_plan", "the assignment is already finished")
			}
			worker, err := loadUser(ctx, s.db, workerID)
			if err != nil || !worker.Active {
				return 400, nil, errOf(400, "invalid_worker", "workerId does not reference an active user")
			}
			if !containsString(worker.Roles, kindRole(a.Kind)) {
				return 409, nil, errOf(409, "ineligible_worker", "the worker is not eligible for this assignment")
			}
			st, _ := sampleTypeForSample(ctx, s, a.SampleID)
			if a.Kind == KindCollection && st != nil && !workerQualified(worker, st) {
				return 409, nil, errOf(409, "ineligible_worker", "the worker is not qualified for this sample type")
			}
			if a.Kind == KindNode && (worker.AssignedLocationID == nil || a.NodeID == nil || *worker.AssignedLocationID != *a.NodeID) {
				return 409, nil, errOf(409, "ineligible_worker", "the worker is not assigned to this node")
			}
			if a.Kind == KindLab && (worker.AssignedLocationID == nil || a.LaboratoryID == nil || *worker.AssignedLocationID != *a.LaboratoryID) {
				return 409, nil, errOf(409, "ineligible_worker", "the worker is not assigned to this laboratory")
			}
			now := nowUTC()
			expires := now.Add(offerTimeout)
			_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$2, offered_at=$3, offer_expires_at=$4,
				accepted_by=NULL, accepted_at=NULL, updated_at=now() WHERE assignment_id=$1`, assignmentID, workerID, now, expires)
			s.audit(ctx, sess, "edit_active_plan", "assignment", assignmentID, true,
				map[string]any{"changeType": body.ChangeType, "workerId": workerID})
			s.emit(ctx, "assignment_offered", "assignment", assignmentID, map[string]any{
				"assignmentId": assignmentID, "workerId": workerID, "kind": a.Kind, "sampleId": a.SampleID,
			}, kindRole(a.Kind), workerID)
		case "add_stop":
			locationID, _ := body.Changes["locationId"].(string)
			if locationID == "" {
				return 400, nil, errOf(400, "invalid_stop", "changes must include locationId")
			}
			l, err := loadLocation(ctx, s.db, locationID)
			if err != nil || !l.Active {
				return 400, nil, errOf(400, "invalid_stop", "locationId must reference an active location")
			}
			dwell := l.HandlingMinutes
			if d, ok := body.Changes["dwellMinutes"].(float64); ok {
				dwell = int(d)
			}
			stops := j.Stops
			if len(stops) == 0 {
				return 409, nil, errOf(409, "invalid_stop_order", "the journey has no stops")
			}
			newStop := map[string]any{
				"stopId": newUUID(), "locationId": locationID, "stopType": "handoff",
				"sequence": len(stops) - 1, "estimatedAt": stops[len(stops)-1]["estimatedAt"], "dwellMinutes": dwell,
			}
			stops = append(stops[:len(stops)-1], newStop, stops[len(stops)-1])
			for i, st := range stops {
				st["sequence"] = i
			}
			stopsJSON, _ := json.Marshal(stops)
			_, _ = s.db.Exec(ctx, `UPDATE journeys SET stops=$2, plan_version=plan_version+1, updated_at=now() WHERE journey_id=$1`, j.JourneyID, stopsJSON)
			s.audit(ctx, sess, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": "add_stop", "locationId": locationID})
		case "remove_stop":
			stopID, _ := body.Changes["stopId"].(string)
			stops := []map[string]any{}
			removed := false
			for _, st := range j.Stops {
				if st["stopId"] == stopID {
					if st["stopType"] != "handoff" {
						return 409, nil, errOf(409, "invalid_stop", "only unfinished handoff stops may be removed")
					}
					removed = true
					continue
				}
				stops = append(stops, st)
			}
			if !removed {
				return 400, nil, errOf(400, "invalid_stop", "stopId not found in this journey")
			}
			for i, st := range stops {
				st["sequence"] = i
			}
			stopsJSON, _ := json.Marshal(stops)
			_, _ = s.db.Exec(ctx, `UPDATE journeys SET stops=$2, plan_version=plan_version+1, updated_at=now() WHERE journey_id=$1`, j.JourneyID, stopsJSON)
			s.audit(ctx, sess, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": "remove_stop", "stopId": stopID})
		case "reorder_stops":
			ids := strSlice(body.Changes["stopIds"])
			if len(ids) != len(j.Stops) {
				return 400, nil, errOf(400, "invalid_stop_order", "stopIds must reorder every stop of the journey")
			}
			byID := map[string]map[string]any{}
			for _, st := range j.Stops {
				id, _ := st["stopId"].(string)
				byID[id] = st
			}
			stops := []map[string]any{}
			for i, id := range ids {
				st, ok := byID[id]
				if !ok {
					return 400, nil, errOf(400, "invalid_stop_order", "stopIds must reorder every stop of the journey")
				}
				if i == 0 && st["stopType"] != "pickup" {
					return 409, nil, errOf(409, "invalid_stop_order", "the pickup stop must remain first")
				}
				if i == len(ids)-1 && st["stopType"] != "delivery" {
					return 409, nil, errOf(409, "invalid_stop_order", "the delivery stop must remain last")
				}
				st["sequence"] = i
				stops = append(stops, st)
			}
			stopsJSON, _ := json.Marshal(stops)
			_, _ = s.db.Exec(ctx, `UPDATE journeys SET stops=$2, plan_version=plan_version+1, updated_at=now() WHERE journey_id=$1`, j.JourneyID, stopsJSON)
			s.audit(ctx, sess, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": "reorder_stops"})
		case "reroute", "replace_route":
			replacementID, status, aerr := s.replanJourney(ctx, sess, j.JourneyID)
			if aerr != nil {
				return aerr.HTTPStatus, nil, aerr
			}
			if status == "exception" {
				return 409, nil, errOf(409, "no_valid_route", "no valid route is available for the remaining work")
			}
			if status == "expired" {
				return 409, nil, errOf(409, "deadline_exceeded", "no route can meet the delivery deadline")
			}
			if replacementID != "" {
				rj, _ := loadJourney(ctx, s.db, replacementID)
				return 201, s.journeyPlanJSON(ctx, rj), nil
			}
		case "cancel_work":
			s.cancelJourneyInternal(ctx, sess, j, "dispatcher edit", JourneyCancelled)
			for _, sid := range journeySampleIDs(ctx, s.db, j.JourneyID) {
				s.setSampleStatus(ctx, sess, sid, SampleCancelled, map[string]any{"journeyId": j.JourneyID})
			}
			s.audit(ctx, sess, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": "cancel_work"})
			j, _ = loadJourney(ctx, s.db, j.JourneyID)
			return 201, s.journeyPlanJSON(ctx, j), nil
		default:
			return 400, nil, errOf(400, "invalid_change_type", "unsupported changeType")
		}
		_, _ = s.db.Exec(ctx, `UPDATE journeys SET plan_version=plan_version+1, updated_at=now() WHERE journey_id=$1 AND status IN ('planned','in_progress')`, j.JourneyID)
		s.emit(ctx, "journey_updated", "journey", j.JourneyID, map[string]any{"journeyId": j.JourneyID}, "", "")
		j, _ = loadJourney(ctx, s.db, j.JourneyID)
		return 201, s.journeyPlanJSON(ctx, j), nil
	})
}
"}

