// sampleTimeline returns the ordered audit history for a sample.
func (s *server) sampleTimeline(ctx context.Context, sampleID string) []map[string]any {
	rows, err := s.db.Query(ctx, `SELECT audit_id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details
		FROM audit_entries
		WHERE (entity_type='sample' AND entity_id=$1)
		   OR (entity_type IN ('assignment','handoff','request') AND details->>'sampleId'=$1)
		ORDER BY id`, sampleID)
	if err != nil {
		return []map[string]any{}
	}
	defer rows.Close()
	out := []map[string]any{}
	for rows.Next() {
		var auditID, actorID, role, action, entityType, entityID string
		var success bool
		var occurredAt time.Time
		var details []byte
		if err := rows.Scan(&auditID, &actorID, &role, &action, &entityType, &entityID, &success, &occurredAt, &details); err != nil {
			continue
		}
		det := map[string]any{}
		if v := jsonAny(details); v != nil {
			if m, ok := v.(map[string]any); ok {
				det = m
			}
		}
		out = append(out, map[string]any{
			"eventId":    auditID,
			"action":     action,
			"actorId":    actorID,
			"role":       role,
			"entityType": entityType,
			"entityId":   entityID,
			"success":    success,
			"occurredAt": fmtTime(occurredAt),
			"details":    det,
		})
	}
	return out
}

func (s *server) sampleStateJSON(ctx context.Context, sm *Sample) map[string]any {
	out := map[string]any{
		"sampleId":       sm.SampleID,
		"requestId":      sm.RequestID,
		"requesterId":    sm.RequesterID,
		"status":         sm.Status,
		"sealed":         sm.Sealed,
		"serviceability": sm.Serviceability,
		"locationStale":  staleSince(sm.LocationRecordedAt),
		"timeline":       s.sampleTimeline(ctx, sm.SampleID),
	}
	if sm.ServiceabilityReason != "" {
		out["serviceabilityReason"] = sm.ServiceabilityReason
	}
	if sm.CurrentHolderID != nil {
		out["currentHolderId"] = *sm.CurrentHolderID
	}
	if sm.ActiveJourneyID != nil {
		out["activeJourneyId"] = *sm.ActiveJourneyID
	}
	if sm.TargetLaboratoryID != nil {
		out["targetLaboratoryId"] = *sm.TargetLaboratoryID
	}
	if sm.LatestLat != nil && sm.LatestLng != nil {
		out["latestLocation"] = map[string]any{"latitude": *sm.LatestLat, "longitude": *sm.LatestLng}
	}
	if sm.LocationRecordedAt != nil {
		out["locationRecordedAt"] = fmtTime(*sm.LocationRecordedAt)
	}
	if sm.Exception != nil {
		out["exception"] = sm.Exception
	}
	if sm.ReceivedLaboratoryID != nil {
		out["receivedLaboratoryId"] = *sm.ReceivedLaboratoryID
	}
	return out
}

// canViewSample checks role-based visibility for a sample.
func (s *server) canViewSample(ctx context.Context, sess *session, sm *Sample) bool {
	switch sess.ActiveRole {
	case RoleAdmin, RoleDispatcher:
		return true
	case RoleRequester:
		return sm.RequesterID == sess.User.UserID
	case RoleCollector, RoleCourier, RoleNode, RoleLab:
		if sm.CurrentHolderID != nil && *sm.CurrentHolderID == sess.User.UserID {
			return true
		}
		var n int
		_ = s.db.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE sample_id=$1 AND (accepted_by=$2 OR offered_to=$2)`,
			sm.SampleID, sess.User.UserID).Scan(&n)
		return n > 0
	}
	return false
}

func (s *server) handleReadSampleState(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if sess.ActiveRole == "" {
		writeErr(w, errOf(409, "role_not_selected", "select an active role before performing this action"))
		return
	}
	ctx := r.Context()
	sm, err := loadSample(ctx, s.db, r.PathValue("sampleId"))
	if err != nil {
		writeErr(w, errOf(404, "not_found", "sample not found"))
		return
	}
	if !s.canViewSample(ctx, sess, sm) {
		writeErr(w, errOf(403, "forbidden", "you may not view this sample"))
		return
	}
	writeData(w, 200, s.sampleStateJSON(ctx, sm))
}

func (s *server) handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if sess.ActiveRole == "" {
		writeErr(w, errOf(409, "role_not_selected", "select an active role before performing this action"))
		return
	}
	ctx := r.Context()
	sm, err := loadSample(ctx, s.db, r.PathValue("sampleId"))
	if err != nil {
		writeErr(w, errOf(404, "not_found", "sample not found"))
		return
	}
	if !s.canViewSample(ctx, sess, sm) {
		writeErr(w, errOf(403, "forbidden", "you may not view this sample"))
		return
	}
	custody := []map[string]any{}
	hrows, err := s.db.Query(ctx, `SELECT handoff_id, sender_id, receiver_id, status, initiated_at, completed_at
		FROM handoffs WHERE sample_id=$1 ORDER BY initiated_at`, sm.SampleID)
	if err == nil {
		for hrows.Next() {
			var hid, sender, receiver, status string
			var initiated time.Time
			var completed *time.Time
			if err := hrows.Scan(&hid, &sender, &receiver, &status, &initiated, &completed); err != nil {
				continue
			}
			entry := map[string]any{
				"handoffId":   hid,
				"fromUserId":  sender,
				"toUserId":    receiver,
				"status":      status,
				"initiatedAt": fmtTime(initiated),
			}
			if completed != nil {
				entry["completedAt"] = fmtTime(*completed)
			}
			custody = append(custody, entry)
		}
		hrows.Close()
	}
	writeData(w, 200, map[string]any{
		"sampleId":  sm.SampleID,
		"requestId": sm.RequestID,
		"timeline":  s.sampleTimeline(ctx, sm.SampleID),
		"custody":   custody,
	})
}

// ---------- role work lists ----------

func (s *server) assignmentWorkItemJSON(ctx context.Context, a *Assignment) map[string]any {
	out := map[string]any{
		"assignmentId": a.AssignmentID,
		"kind":         a.Kind,
		"status":       a.Status,
		"sampleId":     a.SampleID,
		"journeyId":    a.JourneyID,
	}
	if a.FromLocationID != nil {
		out["fromLocationId"] = *a.FromLocationID
	}
	if a.ToLocationID != nil {
		out["toLocationId"] = *a.ToLocationID
	}
	if a.NodeID != nil {
		out["nodeId"] = *a.NodeID
	}
	if a.LaboratoryID != nil {
		out["laboratoryId"] = *a.LaboratoryID
	}
	if a.OfferedTo != nil {
		out["offeredTo"] = *a.OfferedTo
	}
	if a.AcceptedBy != nil {
		out["acceptedBy"] = *a.AcceptedBy
	}
	if sm, err := loadSample(ctx, s.db, a.SampleID); err == nil {
		if req, err := loadRequest(ctx, s.db, sm.RequestID); err == nil {
			out["deadlineAt"] = fmtTime(req.DeliveryDeadline)
		}
		out["history"] = s.sampleTimeline(ctx, a.SampleID)
	}
	// destination capacity for node and laboratory work
	if a.Kind == KindNode && a.NodeID != nil {
		if l, err := loadLocation(ctx, s.db, *a.NodeID); err == nil {
			out["destinationCapacity"] = capacityJSON(l.CapacityUnits, l.ReservedUnits, l.CooledCapacity, l.CooledReserved)
		}
	}
	if a.Kind == KindLab && a.LaboratoryID != nil {
		if l, err := loadLocation(ctx, s.db, *a.LaboratoryID); err == nil {
			out["destinationCapacity"] = capacityJSON(l.CapacityUnits, l.ReservedUnits, l.CooledCapacity, l.CooledReserved)
		}
	}
	return out
}

func (s *server) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		Role         string `json:"role"`
		View         string `json:"view"`
		SampleTypeID string `json:"sampleTypeId"`
	}
	if r.Body != nil && r.ContentLength > 0 {
		if aerr := decodeBody(r, &body); aerr != nil {
			writeErr(w, aerr)
			return
		}
	}
	role := body.Role
	if role == "" {
		role = sess.ActiveRole
	}
	if role == "" {
		writeErr(w, errOf(409, "role_not_selected", "select an active role before performing this action"))
		return
	}
	if !containsString(validRoles, role) {
		writeErr(w, errOf(400, "invalid_role", "role is not a known role"))
		return
	}
	if role != sess.ActiveRole {
		writeErr(w, errOf(403, "forbidden", "work lists follow the currently selected role"))
		return
	}
	view := body.View
	if view == "" {
		view = "pending"
	}
	if !containsString([]string{"pending", "in_progress", "completed"}, view) {
		writeErr(w, errOf(400, "invalid_view", "view must be pending, in_progress or completed"))
		return
	}
	ctx := r.Context()
	items := []map[string]any{}
	switch role {
	case RoleRequester:
		rows, err := s.db.Query(ctx, `SELECT sample_id FROM samples WHERE requester_id=$1 ORDER BY created_at`, sess.User.UserID)
		if err == nil {
			ids := []string{}
			for rows.Next() {
				var id string
				_ = rows.Scan(&id)
				ids = append(ids, id)
			}
			rows.Close()
			for _, id := range ids {
				sm, err := loadSample(ctx, s.db, id)
				if err != nil {
					continue
				}
				if body.SampleTypeID != "" {
					req, err := loadRequest(ctx, s.db, sm.RequestID)
					if err != nil || req.SampleTypeID != body.SampleTypeID {
						continue
					}
				}
				match := false
				switch view {
				case "pending":
					match = !sm.Sealed && sm.Status != SampleCancelled && sm.Status != SampleExpired
				case "in_progress":
					match = sm.Sealed && sm.Status != SampleReceived && sm.Status != SampleCancelled && sm.Status != SampleExpired
				case "completed":
					match = sm.Status == SampleReceived || sm.Status == SampleCancelled || sm.Status == SampleExpired
				}
				if !match {
					continue
				}
				item := s.sampleStateJSON(ctx, sm)
				items = append(items, map[string]any{"kind": "sample", "sample": item})
			}
		}
	case RoleCollector, RoleCourier, RoleNode, RoleLab:
		kind := ""
		switch role {
		case RoleCollector:
			kind = KindCollection
		case RoleCourier:
			kind = KindTransport
		case RoleNode:
			kind = KindNode
		case RoleLab:
			kind = KindLab
		}
		var query string
		var args []any
		switch view {
		case "pending":
			query = `SELECT assignment_id FROM assignments WHERE kind=$1 AND status='offered' AND offered_to=$2 ORDER BY offered_at`
			args = []any{kind, sess.User.UserID}
		case "in_progress":
			query = `SELECT assignment_id FROM assignments WHERE kind=$1 AND accepted_by=$2 AND status IN ('accepted','in_progress') ORDER BY accepted_at`
			args = []any{kind, sess.User.UserID}
		case "completed":
			query = `SELECT assignment_id FROM assignments WHERE kind=$1 AND accepted_by=$2 AND status IN ('completed','cancelled') ORDER BY completed_at NULLS LAST, updated_at DESC LIMIT 200`
			args = []any{kind, sess.User.UserID}
		}
		rows, err := s.db.Query(ctx, query, args...)
		if err == nil {
			ids := []string{}
			for rows.Next() {
				var id string
				_ = rows.Scan(&id)
				ids = append(ids, id)
			}
			rows.Close()
			for _, id := range ids {
				a, err := loadAssignment(ctx, s.db, id)
				if err != nil {
					continue
				}
				if body.SampleTypeID != "" {
					st, err := sampleTypeForSample(ctx, s, a.SampleID)
					if err != nil || st.SampleTypeID != body.SampleTypeID {
						continue
					}
				}
				items = append(items, map[string]any{"kind": "assignment", "assignment": s.assignmentWorkItemJSON(ctx, a)})
			}
		}
	case RoleDispatcher, RoleAdmin:
		statuses := []string{}
		switch view {
		case "pending":
			statuses = []string{JourneyPlanned}
		case "in_progress":
			statuses = []string{JourneyInProgress}
		case "completed":
			statuses = []string{JourneyCompleted, JourneyCancelled, JourneyReplaced, JourneyMerged}
		}
		rows, err := s.db.Query(ctx, `SELECT journey_id FROM journeys WHERE status = ANY($1) ORDER BY created_at DESC LIMIT 300`, statuses)
		if err == nil {
			ids := []string{}
			for rows.Next() {
				var id string
				_ = rows.Scan(&id)
				ids = append(ids, id)
			}
			rows.Close()
			for _, id := range ids {
				j, err := loadJourney(ctx, s.db, id)
				if err != nil {
					continue
				}
				if body.SampleTypeID != "" {
					matchType := false
					for _, sid := range journeySampleIDs(ctx, s.db, j.JourneyID) {
						st, err := sampleTypeForSample(ctx, s, sid)
						if err == nil && st.SampleTypeID == body.SampleTypeID {
							matchType = true
						}
					}
					if !matchType {
						continue
					}
				}
				jw := map[string]any{
					"journeyId":   j.JourneyID,
					"status":      j.Status,
					"routeMode":   j.RouteMode,
					"planVersion": j.PlanVersion,
					"sampleIds":   journeySampleIDs(ctx, s.db, j.JourneyID),
				}
				if j.EstimatedDeliveryAt != nil {
					jw["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
				}
				if j.ReplanStatus != nil {
					jw["replanStatus"] = *j.ReplanStatus
				}
				items = append(items, map[string]any{"kind": "journey", "journey": jw})
			}
		}
	}
	writeData(w, 200, map[string]any{"role": role, "view": view, "items": items})
}

// ---------- bootstrap ----------

func (s *server) handleBootstrap(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	ctx := r.Context()
	out := map[string]any{
		"user":       publicUser(sess.User),
		"serverTime": fmtTime(nowUTC()),
	}
	// sample types are included so request forms can be built
	typeRows, err := s.db.Query(ctx, `SELECT sample_type_id FROM sample_types ORDER BY name`)
	if err == nil {
		ids := []string{}
		for typeRows.Next() {
			var id string
			_ = typeRows.Scan(&id)
			ids = append(ids, id)
		}
		typeRows.Close()
		types := []map[string]any{}
		for _, id := range ids {
			if st, err := loadSampleType(ctx, s.db, id); err == nil {
				types = append(types, sampleTypeJSON(st))
			}
		}
		out["sampleTypes"] = types
	}
	if sess.ActiveRole == RoleRequester {
		samples := []map[string]any{}
		rows, err := s.db.Query(ctx, `SELECT sample_id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC LIMIT 100`, sess.User.UserID)
		if err == nil {
			ids := []string{}
			for rows.Next() {
				var id string
				_ = rows.Scan(&id)
				ids = append(ids, id)
			}
			rows.Close()
			for _, id := range ids {
				if sm, err := loadSample(ctx, s.db, id); err == nil {
					samples = append(samples, s.sampleStateJSON(ctx, sm))
				}
			}
		}
		out["requesterSamples"] = samples
	}
	if sess.ActiveRole == RoleDispatcher || sess.ActiveRole == RoleAdmin || sess.ActiveRole == RoleNode || sess.ActiveRole == RoleLab {
		out["operations"] = s.operationsState(ctx, "")
	}
	writeData(w, 200, out)
}
"}

{"command":"create","path":"/workspace/server/audit.go","file_text":"package main

import (
	"net/http"
	"time"
)

func (s *server) handleSearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		Query string `json:"query"`
		From  string `json:"from"`
		To    string `json:"to"`
	}
	if r.Body != nil && r.ContentLength > 0 {
		if aerr := decodeBody(r, &body); aerr != nil {
			writeErr(w, aerr)
			return
		}
	}
	ctx := r.Context()
	query := `SELECT audit_id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details
		FROM audit_entries WHERE ($1 = '' OR action ILIKE '%' || $1 || '%' OR entity_id::text ILIKE '%' || $1 || '%'
			OR entity_type ILIKE '%' || $1 || '%' OR actor_id::text ILIKE '%' || $1 || '%' OR details::text ILIKE '%' || $1 || '%')`
	args := []any{body.Query}
	if body.From != "" {
		t, ok := parseTime(body.From)
		if !ok {
			writeErr(w, errOf(400, "invalid_time", "from must be an RFC3339 timestamp"))
			return
		}
		args = append(args, t)
		query += ` AND occurred_at >= $2`
	}
	if body.To != "" {
		t, ok := parseTime(body.To)
		if !ok {
			writeErr(w, errOf(400, "invalid_time", "to must be an RFC3339 timestamp"))
			return
		}
		args = append(args, t)
		query += ` AND occurred_at <= $` + itoa(len(args))
	}
	query += ` ORDER BY id DESC LIMIT 500`
	rows, err := s.db.Query(ctx, query, args...)
	if err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	defer rows.Close()
	entries := []map[string]any{}
	for rows.Next() {
		var auditID, actorID, role, action, entityType, entityID string
		var success bool
		var occurredAt time.Time
		var details []byte
		if err := rows.Scan(&auditID, &actorID, &role, &action, &entityType, &entityID, &success, &occurredAt, &details); err != nil {
			continue
		}
		det := map[string]any{}
		if v := jsonAny(details); v != nil {
			if m, ok := v.(map[string]any); ok {
				det = m
			}
		}
		entries = append(entries, map[string]any{
			"auditId":    auditID,
			"actorId":    actorID,
			"role":       role,
			"action":     action,
			"entityType": entityType,
			"entityId":   entityID,
			"success":    success,
			"occurredAt": fmtTime(occurredAt),
			"details":    det,
		})
	}
	writeData(w, 200, map[string]any{"entries": entries})
}
"}

{"command":"create","path":"/workspace/server/main.go","file_text":"package main

import (
	"context"
	"log"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"
	"time"
)

type server struct {
	db     *DB
	static string
}

func main() {
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgres://agent:agent@127.0.0.1:5432/labpickup?sslmode=disable"
	}
	db, err := connectDB(dbURL)
	if err != nil {
		log.Fatalf("database unavailable: %v", err)
	}
	if err := migrate(db); err != nil {
		log.Fatalf("migration failed: %v", err)
	}
	s := &server{db: db, static: os.Getenv("STATIC_DIR")}
	if s.static == "" {
		s.static = "/workspace/web/dist"
	}
	if err := s.seed(context.Background()); err != nil {
		log.Fatalf("seed failed: %v", err)
	}
	if err := s.ensureInitialAdmin(context.Background()); err != nil {
		log.Fatalf("initial admin failed: %v", err)
	}
	go s.offerExpiryLoop()

	mux := http.NewServeMux()
	// auth & session
	mux.HandleFunc("POST /api/auth/login", s.handleLogin)
	mux.HandleFunc("POST /api/auth/logout", s.handleLogout)
	mux.HandleFunc("POST /api/auth/select-role", s.handleSelectRole)
	mux.HandleFunc("POST /api/users/availability", s.handleSetAvailability)
	// admin user management
	mux.HandleFunc("POST /api/admin/users", s.handleCreateUser)
	mux.HandleFunc("POST /api/admin/users/{userId}/roles", s.handleAssignRoles)
	mux.HandleFunc("POST /api/admin/users/{userId}/certifications", s.handleAssignCertifications)
	mux.HandleFunc("POST /api/admin/users/{userId}/assignments", s.handleAssignWorkerSite)
	// admin network management
	mux.HandleFunc("POST /api/admin/locations", s.handleCreateLocation)
	mux.HandleFunc("POST /api/admin/locations/{locationId}", s.handleUpdateLocation)
	mux.HandleFunc("POST /api/admin/locations/{locationId}/acceptance", s.handleSetLaboratoryAcceptance)
	mux.HandleFunc("POST /api/admin/connections", s.handleCreateConnection)
	mux.HandleFunc("POST /api/admin/connections/{connectionId}", s.handleUpdateConnection)
	mux.HandleFunc("POST /api/admin/sample-types", s.handleCreateSampleType)
	mux.HandleFunc("POST /api/admin/sample-types/{sampleTypeId}", s.handleUpdateSampleType)
	mux.HandleFunc("POST /api/admin/locations/{locationId}/capacity", s.handleConfigureCapacity)
	mux.HandleFunc("POST /api/admin/connections/{connectionId}/capacity", s.handleConfigureCapacity)
	// requests & serviceability
	mux.HandleFunc("POST /api/serviceability/check", s.handleServiceabilityCheck)
	mux.HandleFunc("POST /api/requests", s.handleCreateCollectionRequest)
	mux.HandleFunc("POST /api/requests/ingest-presealed", s.handleIngestPresealed)
	// assignment lifecycle
	mux.HandleFunc("POST /api/assignments/accept", s.handleAcceptAssignment)
	mux.HandleFunc("POST /api/assignments/decline", s.handleDeclineAssignment)
	mux.HandleFunc("POST /api/assignments/progress", s.handleUpdateAssignmentProgress)
	mux.HandleFunc("POST /api/assignments/collect-and-seal", s.handleCollectAndSeal)
	mux.HandleFunc("POST /api/assignments/location", s.handleRecordWorkerLocation)
	mux.HandleFunc("POST /api/handling-checkpoints", s.handleRecordHandlingCheckpoint)
	// custody
	mux.HandleFunc("POST /api/handoffs/initiate", s.handleInitiateHandoff)
	mux.HandleFunc("POST /api/handoffs/confirm", s.handleConfirmHandoff)
	mux.HandleFunc("POST /api/laboratory/receipt", s.handleConfirmLaboratoryReceipt)
	mux.HandleFunc("POST /api/laboratory/exceptions", s.handleRecordLaboratoryException)
	// reads
	mux.HandleFunc("POST /api/work/list", s.handleListRoleWork)
	mux.HandleFunc("POST /api/ui/bootstrap", s.handleBootstrap)
	mux.HandleFunc("POST /api/operations/state", s.handleReadOperationsState)
	mux.HandleFunc("GET /api/journeys/{journeyId}", s.handleReadJourneyPlan)
	mux.HandleFunc("GET /api/samples/{sampleId}", s.handleReadSampleState)
	mux.HandleFunc("GET /api/samples/{sampleId}/lifecycle", s.handleReadSampleLifecycle)
	// dispatcher actions
	mux.HandleFunc("POST /api/journeys/cancel", s.handleCancelJourney)
	mux.HandleFunc("POST /api/journeys/split", s.handleSplitJourney)
	mux.HandleFunc("POST /api/journeys/merge", s.handleMergeJourneys)
	mux.HandleFunc("POST /api/journeys/edit", s.handleEditActivePlan)
	mux.HandleFunc("POST /api/journeys/reroute", s.handleRerouteJourney)
	mux.HandleFunc("POST /api/disruptions", s.handleReportDisruption)
	mux.HandleFunc("POST /api/audit/search", s.handleSearchAuditTrail)
	// events
	mux.HandleFunc("GET /api/events", s.handleEvents)

	mux.HandleFunc("GET /ready", func(w http.ResponseWriter, r *http.Request) {
		if err := s.db.Ping(r.Context()); err != nil {
			http.Error(w, `{"status":"unavailable"}`, http.StatusServiceUnavailable)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(200)
		_, _ = w.Write([]byte(`{"status":"ready"}`))
	})
	mux.HandleFunc("/", s.serveStatic)

	addr := os.Getenv("ADDR")
	if addr == "" {
		addr = "127.0.0.1:8080"
	}
	httpServer := &http.Server{Addr: addr, Handler: mux}
	go func() {
		sig := make(chan os.Signal, 1)
		signal.Notify(sig, syscall.SIGINT, syscall.SIGTERM)
		<-sig
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		_ = httpServer.Shutdown(ctx)
	}()
	log.Printf("listening on %s", addr)
	if err := httpServer.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatalf("server failed: %v", err)
	}
}

func (s *server) serveStatic(w http.ResponseWriter, r *http.Request) {
	if strings.HasPrefix(r.URL.Path, "/api/") {
		http.NotFound(w, r)
		return
	}
	p := filepath.Clean(r.URL.Path)
	if p == "/" || p == "." {
		p = "/index.html"
	}
	full := filepath.Join(s.static, p)
	if !strings.HasPrefix(full, filepath.Clean(s.static)) {
		http.NotFound(w, r)
		return
	}
	if info, err := os.Stat(full); err != nil || info.IsDir() {
		// SPA fallback
		full = filepath.Join(s.static, "index.html")
		if _, err := os.Stat(full); err != nil {
			http.NotFound(w, r)
			return
		}
	}
	http.ServeFile(w, r, full)
}

// offerExpiryLoop expires unanswered offers and re-offers them.
func (s *server) offerExpiryLoop() {
	ticker := time.NewTicker(10 * time.Second)
	defer ticker.Stop()
	for range ticker.C {
		ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
		rows, err := s.db.Query(ctx, `SELECT assignment_id FROM assignments WHERE status='offered' AND offer_expires_at < now()`)
		if err != nil {
			cancel()
			continue
		}
		ids := []string{}
		for rows.Next() {
			var id string
			_ = rows.Scan(&id)
			ids = append(ids, id)
		}
		rows.Close()
		for _, id := range ids {
			a, err := loadAssignment(ctx, s.db, id)
			if err != nil || a.Status != AsgOffered {
				continue
			}
			// treat the expired offer as a decline
			if a.OfferedTo != nil {
				declined := append(a.DeclinedBy, *a.OfferedTo)
				dj, _ := jsonMarshal(declined)
				_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, declined_by=$2, updated_at=now()
					WHERE assignment_id=$1`, a.AssignmentID, dj)
				_, _ = s.db.Exec(ctx, `UPDATE users SET recent_declines = recent_declines + 1, last_decline_at=now() WHERE user_id=$1`, *a.OfferedTo)
				s.emit(ctx, "assignment_expired", "assignment", a.AssignmentID, map[string]any{
					"assignmentId": a.AssignmentID, "workerId": *a.OfferedTo, "kind": a.Kind, "sampleId": a.SampleID,
				}, "", "")
			}
			a, _ = loadAssignment(ctx, s.db, id)
			offeredTo, noQualified, _ := s.offerAssignment(ctx, nil, a)
			if noQualified {
				s.flagNoQualifiedWorker(ctx, nil, a.SampleID, a.AssignmentID)
			}
			_ = offeredTo
		}
		cancel()
	}
}

// ensureInitialAdmin creates the first administrator from environment variables.
func (s *server) ensureInitialAdmin(ctx context.Context) error {
	var n int
	if err := s.db.QueryRow(ctx, `SELECT count(*) FROM users`).Scan(&n); err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	username := os.Getenv("ADMIN_USERNAME")
	password := os.Getenv("ADMIN_PASSWORD")
	if username == "" {
		username = "admin"
	}
	if password == "" {
		password = "admin"
	}
	userID := newUUID()
	_, err := s.db.Exec(ctx, `INSERT INTO users (user_id, username, password_hash, display_name, roles, available, capacity_units)
		VALUES ($1,$2,$3,$4,$5,TRUE,4)`, userID, username, hashPassword(password), "Administrator", `["admin","dispatcher"]`)
	if err != nil {
		return err
	}
	s.audit(ctx, nil, "seed_initial_admin", "user", userID, true, map[string]any{"username": username})
	return nil
}

// seed installs the default sample types and, on an empty network, a small
// Bangalore demonstration network so the application is usable immediately.
func (s *server) seed(ctx context.Context) error {
	// default sample types
	defaults := []struct {
		name        string
		container   string
		min, max    float64
		qualified   bool
		cooled      bool
		batching    bool
		incompatIDs []string
	}{}
	_ = defaults
	var amberID, indigoID string
	{
		// look up existing types first (idempotent seeding)
		rows, err := s.db.Query(ctx, `SELECT sample_type_id, name FROM sample_types`)
		if err != nil {
			return err
		}
		existing := map[string]string{}
		for rows.Next() {
			var id, name string
			_ = rows.Scan(&id, &name)
			existing[name] = id
		}
		rows.Close()
		if _, ok := existing["Amber"]; !ok {
			amberID = newUUID()
			if _, err := s.db.Exec(ctx, `INSERT INTO sample_types (sample_type_id, name, container_type, temperature_min_c, temperature_max_c,
				qualified_collector_required, requires_cooled, batching_allowed, incompatible_sample_type_ids)
				VALUES ($1,'Amber','standard',2,25,TRUE,FALSE,TRUE,'[]')`, amberID); err != nil {
				return err
			}
		} else {
			amberID = existing["Amber"]
		}
		if _, ok := existing["Indigo"]; !ok {
			indigoID = newUUID()
			incompat, _ := jsonMarshal([]string{amberID})
			if _, err := s.db.Exec(ctx, `INSERT INTO sample_types (sample_type_id, name, container_type, temperature_min_c, temperature_max_c,
				qualified_collector_required, requires_cooled, batching_allowed, incompatible_sample_type_ids)
				VALUES ($1,'Indigo','standard',2,25,TRUE,FALSE,TRUE,$2)`, indigoID, incompat); err != nil {
				return err
			}
		}
		if _, ok := existing["Frost"]; !ok {
			if _, err := s.db.Exec(ctx, `INSERT INTO sample_types (sample_type_id, name, container_type, temperature_min_c, temperature_max_c,
				qualified_collector_required, requires_cooled, batching_allowed, incompatible_sample_type_ids)
				VALUES ($1,'Frost','cooled',-20,4,TRUE,TRUE,TRUE,'[]')`, newUUID()); err != nil {
				return err
			}
		}
		if _, ok := existing["Pulse"]; !ok {
			if _, err := s.db.Exec(ctx, `INSERT INTO sample_types (sample_type_id, name, container_type, temperature_min_c, temperature_max_c,
				qualified_collector_required, requires_cooled, batching_allowed, incompatible_sample_type_ids)
				VALUES ($1,'Pulse','standard',2,25,TRUE,FALSE,FALSE,'[]')`, newUUID()); err != nil {
				return err
			}
		}
	}
	// demonstration network (only when no locations exist yet)
	var locCount int
	if err := s.db.QueryRow(ctx, `SELECT count(*) FROM locations`).Scan(&locCount); err != nil {
		return err
	}
	if locCount > 0 {
		return nil
	}
	type locDef struct {
		name         string
		lat, lng     float64
		functions    []string
		handling     int
		cap, cooled  int
		acceptsAll   bool
	}
	defs := []locDef{
		{"Indiranagar Collection Centre", 12.9719, 77.6412, []string{"collection_point", "transfer_point"}, 5, 10, 4, false},
		{"Whitefield Collection Point", 12.9698, 77.7500, []string{"collection_point"}, 5, 8, 2, false},
		{"Koramangala Hub", 12.9352, 77.6245, []string{"transfer_point", "hub"}, 8, 20, 8, false},
		{"Hebbal Hub", 13.0358, 77.5970, []string{"transfer_point", "hub"}, 8, 20, 8, false},
		{"Central Laboratory", 12.9716, 77.5946, []string{"laboratory"}, 5, 30, 12, true},
		{"Electronic City Lab & Hub", 12.8452, 77.6602, []string{"transfer_point", "hub", "laboratory"}, 8, 25, 10, true},
	}
	locIDs := []string{}
	for _, d := range defs {
		id := newUUID()
		fn, _ := jsonMarshal(d.functions)
		accepts := []string{}
		if d.acceptsAll {
			rows, err := s.db.Query(ctx, `SELECT sample_type_id FROM sample_types`)
			if err != nil {
				return err
			}
			for rows.Next() {
				var tid string
				_ = rows.Scan(&tid)
				accepts = append(accepts, tid)
			}
			rows.Close()
		}
		acceptsJSON, _ := jsonMarshal(accepts)
		if _, err := s.db.Exec(ctx, `INSERT INTO locations (location_id, name, lat, lng, functions, handling_minutes,
			capacity_units, cooled_capacity_units, accepted_sample_type_ids)
			VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`, id, d.name, d.lat, d.lng, fn, d.handling, d.cap, d.cooled, acceptsJSON); err != nil {
			return err
		}
		locIDs = append(locIDs, id)
	}
	// connections: collection points -> hubs -> laboratories
	type connDef struct {
		from, to int
		minutes  int
		cost     int
		cooled   bool
		cap      int
		ccap     int
	}
	conns := []connDef{
		{0, 2, 20, 2, false, 10, 4}, // Indiranagar -> Koramangala hub
		{0, 3, 35, 3, true, 10, 4},  // Indiranagar -> Hebbal hub (cooled)
		{1, 5, 40, 4, true, 10, 4},  // Whitefield -> Electronic City (cooled)
		{1, 3, 45, 4, false, 10, 4}, // Whitefield -> Hebbal
		{2, 4, 25, 2, true, 12, 6},  // Koramangala -> Central lab (cooled)
		{3, 4, 30, 3, false, 12, 6}, // Hebbal -> Central lab
		{5, 4, 55, 5, true, 12, 6},  // Electronic City -> Central lab (cooled)
		{2, 5, 45, 4, true, 10, 4},  // Koramangala -> Electronic City (cooled)
	}
	for _, c := range conns {
		if _, err := s.db.Exec(ctx, `INSERT INTO connections (connection_id, from_location_id, to_location_id, travel_minutes,
			cost_units, cooled, capacity_units, cooled_capacity_units)
			VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`, newUUID(), locIDs[c.from], locIDs[c.to], c.minutes, c.cost, c.cooled, c.cap, c.ccap); err != nil {
			return err
		}
	}
