{"command":"create","path":"/tmp/extract_components.py","file_text":"import json
spec = json.load(open('/workspace/contracts/openapi.contract.json'))
comps = spec.get('components', {}).get('schemas', {})

def dump(s, indent=0, seen=None):
    if seen is None:
        seen = set()
    if not isinstance(s, dict):
        return str(s)
    if '$ref' in s:
        return s['$ref'].split('/')[-1]
    if 'oneOf' in s:
        return 'oneOf[' + ' | '.join(dump(x, indent, seen) for x in s['oneOf']) + ']'
    if 'anyOf' in s:
        return 'anyOf[' + ' | '.join(dump(x, indent, seen) for x in s['anyOf']) + ']'
    t = s.get('type')
    if t == 'object' or 'properties' in s:
        props = s.get('properties', {})
        req = s.get('required', [])
        lines = []
        for k, v in props.items():
            mark = '*' if k in req else ''
            lines.append('  ' * indent + f"{k}{mark}: {dump(v, indent+1, seen)}")
        return '{\n' + '\n'.join(lines) + '\n' + '  ' * indent + '}'
    if t == 'array':
        return '[' + dump(s.get('items', {}), indent, seen) + ']'
    out = str(t)
    if s.get('enum'):
        out += ' enum:' + str(s['enum'])
    if s.get('nullable'):
        out += ' nullable'
    return out

for name in sorted(comps):
    print('=' * 70)
    print(name)
    print(dump(comps[name]))
"}

