import json
c = json.load(open('contracts/openapi.contract.json'))
def resolve(sch):
    if '\$ref' in sch:
        return {'\$ref': sch['\$ref'].split('/')[-1]}
    return sch
for p, ops in c['paths'].items():
    for m, op in ops.items():
        r = op['responses'].get('200') or op['responses'].get('201')
        if not r: continue
        sch = r.get('content',{}).get('application/json',{}).get('schema',{})
        data = sch.get('properties',{}).get('data',{})
        code = '200' if '200' in op['responses'] else '201'
        if '\$ref' in data:
            print(op['operationId'], code, '=> \$ref', data['\$ref'].split('/')[-1])
            continue
        props = data.get('properties',{})
        req = data.get('required',[])
        parts=[]
        for k,v in props.items():
            t = v.get('type','?')
            if '\$ref' in v: t='ref:'+v['\$ref'].split('/')[-1]
            if 'allOf' in v: t='allOf:'+','.join(x.get('\$ref','?').split('/')[-1] for x in v['allOf'])
            parts.append(k+('*' if k in req else '')+':'+t)
        print(op['operationId'], code, '=>', ', '.join(parts) if parts else '(empty)')
"","summary":"Dump all success response data schemas"}

