{"command":"create","path":"/workspace/web/src/App.tsx","file_text":"import { useCallback, useEffect, useState } from "react";
import { api, getToken, setToken, ApiRequestError } from "./api";
import type { Bootstrap, Role, User } from "./types";
import { ROLE_LABELS } from "./types";
import { WorkView } from "./views/work";
import { SampleView } from "./views/sample";
import { RequesterView } from "./views/requester";
import { MonitorView, AuditView } from "./views/monitor";
import { AdminView, LabView } from "./views/admin";

type Tab =
  | "work"
  | "samples"
  | "request"
  | "laboratory"
  | "monitor"
  | "audit"
  | "admin";

function Login({ onLogin }: { onLogin: () => void }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setBusy(true);
    try {
      const res = await api.post<{ data: { sessionToken: string } }>(
        "/api/authenticate-user",
        { username, password },
      );
      setToken(res.data.sessionToken);
      onLogin();
    } catch (err) {
      if (err instanceof ApiRequestError) setError(err.message);
      else setError("Sign-in failed. Please try again.");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div style={{ maxWidth: 380, margin: "80px auto" }}>
      <div className="card">
        <h1 style={{ fontSize: 20 }}>Lab Sample Pickup &amp; Delivery</h1>
        <p className="muted">Sign in to continue</p>
        <form onSubmit={submit}>
          <div className="field">
            <label htmlFor="login-username">Username</label>
            <input
              id="login-username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              autoComplete="username"
              style={{ width: "100%" }}
            />
          </div>
          <div className="field">
            <label htmlFor="login-password">Password</label>
            <input
              id="login-password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              autoComplete="current-password"
              style={{ width: "100%" }}
            />
          </div>
          {error && (
            <div className="alert error" role="alert">
              {error}
            </div>
          )}
          <button className="primary" type="submit" disabled={busy} style={{ width: "100%" }}>
            Sign in
          </button>
        </form>
      </div>
    </div>
  );
}

export default function App() {
  const [user, setUser] = useState<User | null>(null);
  const [activeRole, setActiveRole] = useState<Role | null>(null);
  const [tab, setTab] = useState<Tab>("work");
  const [loading, setLoading] = useState(true);
  const [authError, setAuthError] = useState<string | null>(null);
  const [sampleFocus, setSampleFocus] = useState<string | null>(null);

  const loadBootstrap = useCallback(async () => {
    try {
      const res = await api.get<{ data: Bootstrap }>("/api/ui/bootstrap");
      const u = res.data.user;
      setUser(u);
      setActiveRole((u.activeRole as Role) ?? u.roles[0] ?? null);
      setAuthError(null);
    } catch (err) {
      if (err instanceof ApiRequestError && err.status === 401) {
        setToken(null);
        setUser(null);
      } else {
        setAuthError("Could not load session. Is the server running?");
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (getToken()) void loadBootstrap();
    else setLoading(false);
  }, [loadBootstrap]);

  const switchRole = async (role: Role) => {
    try {
      await api.post("/api/select-active-role", { role });
      setActiveRole(role);
      setTab("work");
    } catch (err) {
      if (err instanceof ApiRequestError) setAuthError(err.message);
    }
  };

  const signOut = () => {
    setToken(null);
    setUser(null);
    setActiveRole(null);
    setTab("work");
  };

  const openSample = (sampleId: string) => {
    setSampleFocus(sampleId);
    setTab("samples");
  };

  if (loading) return <p style={{ padding: 24 }}>Loading…</p>;
  if (!user) return <Login onLogin={loadBootstrap} />;

  const role = activeRole ?? user.roles[0];
  const tabs: { id: Tab; label: string }[] = [
    { id: "work", label: "My work" },
    { id: "samples", label: "Samples" },
  ];
  if (role === "requester") tabs.push({ id: "request", label: "New request" });
  if (role === "laboratory_intake_operator") tabs.push({ id: "laboratory", label: "Laboratory" });
  if (role === "dispatcher" || role === "administrator") {
    tabs.push({ id: "monitor", label: "Monitor" });
    tabs.push({ id: "audit", label: "Audit" });
  }
  if (role === "administrator") tabs.push({ id: "admin", label: "Administration" });

  return (
    <div style={{ maxWidth: 1100, margin: "0 auto", padding: 16 }}>
      <header
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          flexWrap: "wrap",
          gap: 12,
          marginBottom: 16,
        }}
      >
        <div>
          <h1 style={{ fontSize: 20, margin: 0 }}>Lab Sample Pickup &amp; Delivery</h1>
          <span className="muted">
            Signed in as {user.displayName ?? user.username}
          </span>
        </div>
        <div className="row">
          <div className="field">
            <label htmlFor="active-role">Active role</label>
            <select
              id="active-role"
              value={role ?? ""}
              onChange={(e) => void switchRole(e.target.value as Role)}
            >
              {user.roles.map((r) => (
                <option key={r} value={r}>
                  {ROLE_LABELS[r] ?? r}
                </option>
              ))}
            </select>
          </div>
          <button onClick={signOut}>Sign out</button>
        </div>
      </header>

      {authError && (
        <div className="alert error" role="alert">
          {authError}
        </div>
      )}

      <nav className="tabs" aria-label="Main views">
        {tabs.map((t) => (
          <button
            key={t.id}
            className={tab === t.id ? "active" : ""}
            onClick={() => setTab(t.id)}
          >
            {t.label}
          </button>
        ))}
      </nav>

      <main>
        {tab === "work" && role && <WorkView role={role} onOpenSample={openSample} />}
        {tab === "samples" && (
          <SampleView focusSampleId={sampleFocus} onConsumeFocus={() => setSampleFocus(null)} />
        )}
        {tab === "request" && <RequesterView onCreated={openSample} />}
        {tab === "laboratory" && <LabView user={user} />}
        {tab === "monitor" && <MonitorView onOpenSample={openSample} />}
        {tab === "audit" && <AuditView />}
        {tab === "admin" && <AdminView />}
      </main>
    </div>
  );
}
"}

{"command":"create","path":"/workspace/web/src/views/work.tsx","file_text":"import { useCallback, useEffect, useState } from "react";
import { api, newIdempotencyKey, ApiRequestError } from "../api";
import type { Role, RoleWork, TimelineEntry, WorkItem } from "../types";

export function Timeline({ entries }: { entries: TimelineEntry[] }) {
  const ordered = [...entries].sort((a, b) => a.eventId - b.eventId);
  if (ordered.length === 0) return <p className="muted">No history yet.</p>;
  return (
    <ol className="timeline" aria-label="Status timeline">
      {ordered.map((e) => (
        <li key={e.eventId} className={e.success ? "" : "failure"}>
          <strong>{e.action}</strong>{" "}
          <span className="muted">
            {new Date(e.occurredAt).toLocaleString()} · role {e.role || "—"}
            {e.success ? "" : " · failed"}
          </span>
        </li>
      ))}
    </ol>
  );
}

function LocationRecorder({
  assignmentId,
  onDone,
}: {
  assignmentId: string;
  onDone: (msg: string) => void;
}) {
  const [lat, setLat] = useState("");
  const [lng, setLng] = useState("");
  const [seq, setSeq] = useState(1);
  const [error, setError] = useState<string | null>(null);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    try {
      await api.post("/api/record-worker-location", {
        assignmentId,
        coordinate: { lat: Number(lat), lng: Number(lng) },
        sequence: seq,
        recordedAt: new Date().toISOString(),
      });
      setSeq(seq + 1);
      onDone(`Location recorded (${lat}, ${lng})`);
    } catch (err) {
      setError(err instanceof ApiRequestError ? err.message : "Failed to record location");
    }
  };

  return (
    <form onSubmit={submit} className="row" style={{ marginTop: 8 }}>
      <div className="field">
        <label htmlFor={`lat-${assignmentId}`}>Latitude</label>
        <input
          id={`lat-${assignmentId}`}
          value={lat}
          onChange={(e) => setLat(e.target.value)}
          required
          inputMode="decimal"
        />
      </div>
      <div className="field">
        <label htmlFor={`lng-${assignmentId}`}>Longitude</label>
        <input
          id={`lng-${assignmentId}`}
          value={lng}
          onChange={(e) => setLng(e.target.value)}
          required
          inputMode="decimal"
        />
      </div>
      <button type="submit" className="primary">
        Record location
      </button>
      {error && (
        <div className="alert error" role="alert" style={{ width: "100%" }}>
          {error}
        </div>
      )}
    </form>
  );
}

function WorkItemCard({
  item,
  onOpenSample,
  onAction,
}: {
  item: WorkItem;
  onOpenSample: (id: string) => void;
  onAction: () => void;
}) {
  const [showHistory, setShowHistory] = useState(false);
  const [showLocation, setShowLocation] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const act = async (op: string, body: Record<string, unknown>, ok: string) => {
    setBusy(true);
    setError(null);
    setMessage(null);
    try {
      await api.post(op, body);
      setMessage(ok);
      onAction();
    } catch (err) {
      setError(err instanceof ApiRequestError ? err.message : "Action failed");
    } finally {
      setBusy(false);
    }
  };

  const isAssignment = item.kind !== "sample" && item.kind !== "journey" && item.assignmentId;
  const offered = item.status === "offered" || item.status === "pending";
  const accepted = item.status === "accepted" || item.status === "in_progress";

  return (
    <div className="card">
      <div>
        <strong>{item.kind}</strong>
        <span className="badge status">{item.status}</span>
        {item.locationStale && <span className="badge stale">Stale location</span>}
      </div>
      <div className="muted" style={{ margin: "4px 0" }}>
        {item.assignmentId && <span>Assignment {item.assignmentId} · </span>}
        {item.sampleId && <span>Sample {item.sampleId} · </span>}
        {item.journeyId && <span>Journey {item.journeyId}</span>}
        {item.deliveryDeadline && (
          <span> · deadline {new Date(item.deliveryDeadline).toLocaleString()}</span>
        )}
      </div>
      <div className="row">
        {item.sampleId && (
          <button onClick={() => onOpenSample(item.sampleId!)}>View sample</button>
        )}
        {isAssignment && offered && (
          <>
            <button
              className="primary"
              disabled={busy}
              onClick={() =>
                void act(
                  "/api/accept-assignment",
                  { assignmentId: item.assignmentId, idempotencyKey: newIdempotencyKey() },
                  "Assignment accepted",
                )
              }
            >
              Accept assignment
            </button>
            <button
              className="danger"
              disabled={busy}
              onClick={() =>
                void act(
                  "/api/decline-assignment",
                  { assignmentId: item.assignmentId, idempotencyKey: newIdempotencyKey() },
                  "Assignment declined",
                )
              }
            >
              Decline assignment
            </button>
          </>
        )}
        {isAssignment && accepted && (
          <button onClick={() => setShowLocation((v) => !v)}>
            {showLocation ? "Hide location form" : "Record location"}
          </button>
        )}
        <button onClick={() => setShowHistory((v) => !v)}>
          {showHistory ? "Hide history" : "Show history"}
        </button>
      </div>
      {message && (
        <div className="alert success" role="status">
          {message}
        </div>
      )}
      {error && (
        <div className="alert error" role="alert">
          {error}
        </div>
      )}
      {showLocation && item.assignmentId && (
        <LocationRecorder assignmentId={item.assignmentId} onDone={setMessage} />
      )}
      {showHistory && <Timeline entries={item.history ?? []} />}
    </div>
  );
}

export function WorkView({
  role,
  onOpenSample,
}: {
  role: Role;
  onOpenSample: (id: string) => void;
}) {
