{"command":"create","path":"/workspace/web/src/views/sample.tsx","file_text":"import { useCallback, useEffect, useState } from "react";
import { api, ApiRequestError } from "../api";
import type { JourneyPlan, SampleState, TimelineEntry } from "../types";
import { Timeline } from "./work";

interface Lifecycle {
  sampleId: string;
  currentHolderId?: string;
  custodyHolderId?: string;
  timeline?: TimelineEntry[];
  history?: TimelineEntry[];
  exception?: Record<string, unknown> | null;
}

export function SampleView({
  focusSampleId,
  onConsumeFocus,
}: {
  focusSampleId: string | null;
  onConsumeFocus: () => void;
}) {
  const [sampleId, setSampleId] = useState("");
  const [state, setState] = useState<SampleState | null>(null);
  const [lifecycle, setLifecycle] = useState<Lifecycle | null>(null);
  const [plan, setPlan] = useState<JourneyPlan | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const load = useCallback(async (id: string) => {
    setBusy(true);
    setError(null);
    setState(null);
    setLifecycle(null);
    setPlan(null);
    try {
      const res = await api.get<{ data: SampleState }>(`/api/read-sample-state/${id}`);
      const s = res.data;
      setState(s);
      try {
        const lc = await api.post<{ data: Lifecycle }>("/api/read-sample-lifecycle", {
          sampleId: id,
        });
        setLifecycle(lc.data);
      } catch {
        setLifecycle(null);
      }
      if (s.activeJourneyId) {
        try {
          const jp = await api.post<{ data: JourneyPlan }>("/api/read-journey-plan", {
            journeyId: s.activeJourneyId,
          });
          setPlan(jp.data);
        } catch {
          setPlan(null);
        }
      }
    } catch (err) {
      setError(err instanceof ApiRequestError ? err.message : "Failed to load sample");
    } finally {
      setBusy(false);
    }
  }, []);

  useEffect(() => {
    if (focusSampleId) {
      setSampleId(focusSampleId);
      void load(focusSampleId);
      onConsumeFocus();
    }
  }, [focusSampleId, load, onConsumeFocus]);

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    if (sampleId.trim()) void load(sampleId.trim());
  };

  const status = state?.state?.status ?? state?.status;
  const holder = lifecycle?.currentHolderId ?? lifecycle?.custodyHolderId ?? state?.currentHolderId;
  const exception = state?.exception ?? lifecycle?.exception ?? null;
  const timeline = lifecycle?.timeline ?? lifecycle?.history ?? state?.timeline ?? [];
  const legs = plan?.legs ?? [];
  const completedLegs = legs.filter((l) => l.status === "completed").length;

  return (
    <div>
      <form onSubmit={submit} className="row" style={{ marginBottom: 16 }}>
        <div className="field">
          <label htmlFor="sample-id">Sample ID</label>
          <input
            id="sample-id"
            value={sampleId}
            onChange={(e) => setSampleId(e.target.value)}
            placeholder="00000000-0000-0000-0000-000000000000"
            style={{ width: 340 }}
          />
        </div>
        <button type="submit" className="primary" disabled={busy}>
          Load sample
        </button>
      </form>

      {error && (
        <div className="alert error" role="alert">
          {error}
        </div>
      )}

      {state && (
        <div className="card">
          <h2 style={{ marginTop: 0, fontSize: 17 }}>
            Sample {state.sampleId}
            {status && <span className="badge status">{status}</span>}
            {exception && <span className="badge exception">Exception</span>}
            {state.locationStale ? (
              <span className="badge stale">Stale</span>
            ) : (
              <span className="badge fresh">Fresh</span>
            )}
          </h2>
          <table>
            <tbody>
              <tr>
                <th>Status</th>
                <td>{status ?? "—"}</td>
              </tr>
              <tr>
                <th>Serviceability</th>
                <td>{state.serviceability}</td>
              </tr>
              <tr>
                <th>Current custodian</th>
                <td>{holder ?? "—"}</td>
              </tr>
              <tr>
                <th>Last known location</th>
                <td>
                  {state.latestLocation
                    ? `${state.latestLocation.lat}, ${state.latestLocation.lng}`
                    : "—"}
                </td>
              </tr>
              <tr>
                <th>Last update</th>
                <td>
                  {state.locationRecordedAt
                    ? new Date(state.locationRecordedAt).toLocaleString()
                    : "—"}
                </td>
              </tr>
              <tr>
                <th>Delivery deadline</th>
                <td>{new Date(state.deliveryDeadline).toLocaleString()}</td>
              </tr>
              <tr>
                <th>Origin</th>
                <td>
                  {state.originType} ({state.origin.lat}, {state.origin.lng})
                </td>
              </tr>
            </tbody>
          </table>

          {exception && (
            <div className="alert error" role="alert">
              Exception: {JSON.stringify(exception)}
            </div>
          )}

          {plan && (
            <section aria-label="Route progress" style={{ marginTop: 12 }}>
              <h3 style={{ fontSize: 15 }}>Route progress</h3>
              <p>
                Journey {plan.journeyId} · plan v{plan.planVersion} · {plan.routeMode} ·{" "}
                {completedLegs}/{legs.length} legs completed
              </p>
              {plan.orderedStops && plan.orderedStops.length > 0 && (
                <ol>
                  {plan.orderedStops.map((s) => (
                    <li key={s.stopId}>
                      {s.stopType} @ {s.locationId} — est.{" "}
                      {new Date(s.estimatedAt).toLocaleString()}
                      {s.completedAt
                        ? ` · completed ${new Date(s.completedAt).toLocaleString()}`
                        : ""}
                    </li>
                  ))}
                </ol>
              )}
            </section>
          )}

          <section aria-label="Sample timeline" style={{ marginTop: 12 }}>
            <h3 style={{ fontSize: 15 }}>Timeline</h3>
            <Timeline entries={timeline} />
          </section>
        </div>
      )}
    </div>
  );
}
"}

{"command":"create","path":"/workspace/web/src/views/requester.tsx","file_text":"import { useState } from "react";
import { api, newIdempotencyKey, ApiRequestError } from "../api";
import { SAMPLE_TYPES } from "../types";

function toIso(local: string): string {
  return new Date(local).toISOString();
}

interface FormState {
  lat: string;
  lng: string;
  originType: string;
  sampleTypeId: string;
  deliveryDeadline: string;
  earliestCollection: string;
  latestCollection: string;
  containerType: string;
  tempMin: string;
  tempMax: string;
}

const defaultForm = (): FormState => {
  const now = Date.now();
  const toLocal = (t: number) => {
    const d = new Date(t);
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0, 16);
  };
  return {
    lat: "12.9716",
    lng: "77.5946",
    originType: "home",
    sampleTypeId: SAMPLE_TYPES[0].id,
    deliveryDeadline: toLocal(now + 24 * 3600 * 1000),
    earliestCollection: toLocal(now + 3600 * 1000),
    latestCollection: toLocal(now + 4 * 3600 * 1000),
    containerType: "standard",
    tempMin: "2",
    tempMax: "8",
  };
};

export function RequesterView({ onCreated }: { onCreated: (sampleId: string) => void }) {
  const [form, setForm] = useState<FormState>(defaultForm());
  const [checkResult, setCheckResult] = useState<string | null>(null);
  const [checkOk, setCheckOk] = useState<boolean | null>(null);
  const [createMsg, setCreateMsg] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const set = (k: keyof FormState) => (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) =>
    setForm((f) => ({ ...f, [k]: e.target.value }));

  const baseBody = () => ({
    origin: { lat: Number(form.lat), lng: Number(form.lng) },
    originType: form.originType,
    sampleTypeId: form.sampleTypeId,
    deliveryDeadline: toIso(form.deliveryDeadline),
    earliestCollectionAt: toIso(form.earliestCollection),
    latestCollectionAt: toIso(form.latestCollection),
  });

  const check = async (e: React.FormEvent) => {
    e.preventDefault();
    setBusy(true);
    setError(null);
    setCheckResult(null);
    setCreateMsg(null);
    try {
      const res = await api.post<{ data: { serviceable: boolean; reason?: string } }>(
        "/api/check-serviceability",
        baseBody(),
      );
      setCheckOk(res.data.serviceable);
      setCheckResult(
        res.data.serviceable
          ? "Serviceable — a laboratory can receive this sample before its deadline."
          : `Not serviceable${res.data.reason ? `: ${res.data.reason}` : ""}`,
      );
    } catch (err) {
      setCheckOk(false);
      setCheckResult(err instanceof ApiRequestError ? err.message : "Serviceability check failed");
    } finally {
      setBusy(false);
    }
  };

  const create = async (e: React.FormEvent) => {
    e.preventDefault();
    setBusy(true);
    setError(null);
    setCreateMsg(null);
    setCheckResult(null);
    try {
      const res = await api.post<{ data: { requestId: string; sampleId: string } }>(
        "/api/create-collection-request",
        {
          ...baseBody(),
          requestedAt: new Date().toISOString(),
          containerType: form.containerType,
          temperatureMinC: Number(form.tempMin),
          temperatureMaxC: Number(form.tempMax),
          idempotencyKey: newIdempotencyKey(),
        },
      );
      setCreateMsg(
        `Request created. Request ${res.data.requestId} · Sample ${res.data.sampleId}`,
      );
      onCreated(res.data.sampleId);
    } catch (err) {
      setError(err instanceof ApiRequestError ? err.message : "Failed to create request");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="card" style={{ maxWidth: 560 }}>
      <h2 style={{ marginTop: 0, fontSize: 17 }}>New collection request</h2>
      <form>
        <div className="row">
          <div className="field">
            <label htmlFor="req-lat">Origin latitude</label>
            <input id="req-lat" value={form.lat} onChange={set("lat")} required inputMode="decimal" />
          </div>
          <div className="field">
            <label htmlFor="req-lng">Origin longitude</label>
            <input id="req-lng" value={form.lng} onChange={set("lng")} required inputMode="decimal" />
          </div>
          <div className="field">
            <label htmlFor="req-origin-type">Origin type</label>
            <select id="req-origin-type" value={form.originType} onChange={set("originType")}>
              <option value="home">Home</option>
              <option value="clinic">Clinic</option>
              <option value="node">Network node</option>
            </select>
          </div>
        </div>
        <div className="row" style={{ marginTop: 12 }}>
          <div className="field">
            <label htmlFor="req-sample-type">Sample type</label>
            <select id="req-sample-type" value={form.sampleTypeId} onChange={set("sampleTypeId")}>
              {SAMPLE_TYPES.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.name}
                </option>
              ))}
            </select>
          </div>
          <div className="field">
            <label htmlFor="req-container">Container type</label>
            <input id="req-container" value={form.containerType} onChange={set("containerType")} />
          </div>
          <div className="field">
            <label htmlFor="req-tmin">Temp min (°C)</label>
            <input id="req-tmin" value={form.tempMin} onChange={set("tempMin")} inputMode="decimal" />
          </div>
          <div className="field">
            <label htmlFor="req-tmax">Temp max (°C)</label>
            <input id="req-tmax" value={form.tempMax} onChange={set("tempMax")} inputMode="decimal" />
          </div>
        </div>
        <div className="row" style={{ marginTop: 12 }}>
          <div className="field">
            <label htmlFor="req-earliest">Earliest collection</label>
            <input
              id="req-earliest"
              type="datetime-local"
              value={form.earliestCollection}
              onChange={set("earliestCollection")}
              required
            />
          </div>
          <div className="field">
            <label htmlFor="req-latest">Latest collection</label>
            <input
              id="req-latest"
              type="datetime-local"
              value={form.latestCollection}
              onChange={set("latestCollection")}
              required
            />
          </div>
          <div className="field">
            <label htmlFor="req-deadline">Delivery deadline</label>
            <input
              id="req-deadline"
              type="datetime-local"
              value={form.deliveryDeadline}
              onChange={set("deliveryDeadline")}
              required
            />
          </div>
        </div>
        <div className="row" style={{ marginTop: 16 }}>
          <button onClick={(e) => void check(e)} disabled={busy}>
            Check serviceability
          </button>
          <button className="primary" onClick={(e) => void create(e)} disabled={busy}>
            Create collection request
          </button>
        </div>
      </form>

      {checkResult && (
        <div className={`alert ${checkOk ? "success" : "error"}`} role="status">
          {checkResult}
          <div className="muted">
            Dry run only — no request, sample, journey, assignment or capacity reservation was
            created.
          </div>
        </div>
      )}
      {createMsg && (
        <div className="alert success" role="status">
          {createMsg}
        </div>
      )}
      {error && (
        <div className="alert error" role="alert">
          {error}
        </div>
      )}
    </div>
  );
}
"}

{"command":"create","path":"/workspace/web/src/views/monitor.tsx","file_text":"import { useCallback, useEffect, useState } from "react";
import { api, ApiRequestError } from "../api";
import type { AuditEntry, AuditSearchResult, OperationsState } from "../types";
import { NetworkMap, type MapMarker } from "../map";

export function MonitorView({ onOpenSample }: { onOpenSample: (id: string) => void }) {
  const [ops, setOps] = useState<OperationsState | null>(null);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const res = await api.post<{ data: OperationsState }>("/api/read-operations-state", {});
      setOps(res.data);
      setError(null);
    } catch (err) {
      setError(err instanceof ApiRequestError ? err.message : "Failed to load operations state");
    }
  }, []);

  useEffect(() => {
    void load();
    const t = setInterval(() => void load(), 15000);
    return () => clearInterval(t);
  }, [load]);

  if (error)
    return (
      <div className="alert error" role="alert">
        {error}
      </div>
    );
  if (!ops) return <p>Loading operations state…</p>;

  const markers: MapMarker[] = (ops.locations ?? []).map((l) => ({
    id: l.locationId ?? l.id,
    coordinate: l.coordinate,
    kind: l.functions?.laboratory ? "laboratory" : "location",
    label: l.name,
  }));
  for (const w of ops.workers ?? []) {
    const c = (w as any).latestLocation ?? (w as any).coordinate;
    if (c && typeof c.lat === "number") {
      markers.push({
        id: String((w as any).workerId ?? (w as any).userId ?? Math.random()),
        coordinate: c,
        kind: "worker",
        label: String((w as any).displayName ?? (w as any).username ?? "worker"),
      });
    }
  }
  for (const s of ops.samples ?? []) {
    const c = (s as any).latestLocation;
    if (c && typeof c.lat === "number") {
      markers.push({
        id: String((s as any).sampleId),
        coordinate: c,
        kind: "sample",
        label: `sample ${String((s as any).sampleId).slice(0, 8)}`,
      });
    }
  }

  const cards: { label: string; value: number }[] = [
    { label: "Samples", value: ops.samples?.length ?? 0 },
    { label: "Workers", value: ops.workers?.length ?? 0 },
    { label: "Locations", value: ops.locations?.length ?? 0 },
    { label: "Connections", value: ops.connections?.length ?? 0 },
    { label: "Routes", value: ops.routes?.length ?? 0 },
    { label: "Handoffs", value: ops.handoffs?.length ?? 0 },
    { label: "Delays", value: ops.delays?.length ?? 0 },
    { label: "Exceptions", value: ops.exceptions?.length ?? 0 },
  ];

  return (
    <div>
      <div className="grid" aria-label="Operations summary">
        {cards.map((c) => (
          <div className="stat" key={c.label}>
            <div className="num">{c.value}</div>
            <div className="muted">{c.label}</div>
          </div>
        ))}
      </div>

      <h2 style={{ fontSize: 17, marginTop: 20 }}>Live network map</h2>
      <NetworkMap markers={markers} />
      <p className="muted">
        Blue: network locations · Purple: laboratories · Green: workers · Orange: samples
      </p>

      <h2 style={{ fontSize: 17 }}>Exceptions</h2>
      {(ops.exceptions ?? []).length === 0 && <p className="muted">No active exceptions.</p>}
      {(ops.exceptions ?? []).map((x, i) => (
        <div className="card" key={i}>
          <span className="badge exception">Exception</span>{" "}
          <code style={{ fontSize: 12 }}>{JSON.stringify(x)}</code>
        </div>
      ))}

      <h2 style={{ fontSize: 17 }}>Samples</h2>
      <table>
        <thead>
          <tr>
            <th>Sample</th>
            <th>Status</th>
            <th>Holder</th>
            <th>Last update</th>
            <th>Freshness</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {(ops.samples ?? []).map((s, i) => {
            const rec = s as any;
            return (
              <tr key={rec.sampleId ?? i}>
                <td>{String(rec.sampleId ?? "").slice(0, 13)}…</td>
                <td>{rec.status ?? rec.state?.status ?? "—"}</td>
                <td>{rec.currentHolderId ? String(rec.currentHolderId).slice(0, 13) + "…" : "—"}</td>
                <td>
                  {rec.locationRecordedAt
                    ? new Date(rec.locationRecordedAt).toLocaleString()
                    : "—"}
                </td>
                <td>
                  {rec.locationStale ? (
                    <span className="badge stale">Stale</span>
                  ) : (
                    <span className="badge fresh">Fresh</span>
                  )}
                </td>
                <td>
                  {rec.sampleId && (
                    <button onClick={() => onOpenSample(String(rec.sampleId))}>View</button>
                  )}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

